  coffee: { eyebrow: 'COFFEE / 咖啡业务', title: '咖啡业务', desc: '采购、生产、库存与渠道销售在这里协同。', tabs: ['采购管理', '库存管理', '经营分析'] },
  bike: { eyebrow: 'BIKE / 自行车业务', title: '自行车业务', desc: '收口 ALSVID 采购与财务数据，保留外部系统作为产品和库存事实来源。', tabs: ['采购与付款节点', '到岸成本归集', '销售与利润'] },
