type ActivityItem={id:string;icon:React.ElementType;tint:string;title:string;detail:string;time:string;amount:string;state:string;stateColor:string}

function App() {
  const [active, setActive] = useState<Module>('overview')
  const [tab, setTab] = useState<Tab>('overview')
  const [sideOpen, setSideOpen] = useState(true)
  const [openTabs, setOpenTabs] = useState<OpenTab[]>([{ key: 'overview|overview', module: 'overview', tab: 'overview', label: moduleCopy.overview.tabs[0] }])
  // 打开/激活一个二级页面为标签（同一页面不重复开）
  function openPage(module: Module, t: Tab) {
    const label = moduleCopy[module].tabs[tabIndexOf(t)]
    const key = `${module}|${t}`
    setActive(module); setTab(t)
    setOpenTabs(prev => prev.some(x => x.key === key) ? prev : [...prev, { key, module, tab: t, label }])
  }
  function activateTab(item: OpenTab) { setActive(item.module); setTab(item.tab) }
  function closeTab(key: string, e: React.MouseEvent) {
    e.stopPropagation()
    setOpenTabs(prev => {
      const next = prev.filter(x => x.key !== key)
      if (key === `${active}|${tab}` && next.length) { const fb = next[next.length - 1]; setActive(fb.module); setTab(fb.tab) }
      return next
    })
  }
  function closeAllTabs() {
    const cur = { key: `${active}|${tab}`, module: active, tab, label: moduleCopy[active].tabs[tabIndexOf(tab)] }
    setOpenTabs([cur])
  }
  const [drawer, setDrawer] = useState(false)
  const [quickCreate, setQuickCreate] = useState<{kind:'purchase'|'sales';requestId:string}|null>(null)
  const [query, setQuery] = useState('')
  const [periodOpen, setPeriodOpen] = useState(false)
  const [financeFocus,setFinanceFocus]=useState<'bank'|'items'|'invoices'|'expenses'|'journals'>('bank')
  const now = new Date()
  const currentPeriod = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`
  const [inventory, setInventory] = useState<InventoryRow[]>([])
  const [safetyStocks,setSafetyStocks]=useState<SafetyStockRow[]>([])
  const [inventoryMovements,setInventoryMovements]=useState<InventoryMovement[]>([])
  const [packagingRules,setPackagingRules]=useState<PackagingRule[]>([])
  const [purchases, setPurchases] = useState<PurchaseRow[]>([])
  const [openItems,setOpenItems]=useState<OpenItem[]>([])
  const [expenses,setExpenses]=useState<ExpenseRow[]>([])
  const [projects,setProjects]=useState<ProjectRow[]>([])
  const [sampleDispatches,setSampleDispatches]=useState<SampleDispatchRow[]>([])
  const [bikeOrders,setBikeOrders]=useState<BikeOrder[]>([])
  const [bikeCosts,setBikeCosts]=useState<BikeLandedCost[]>([])
  const [bikeSales,setBikeSales]=useState<BikeSale[]>([])
  const [bankRows,setBankRows]=useState<BankRow[]>([])
  const [invoices,setInvoices]=useState<InvoiceRow[]>([])
  const [periodLocks,setPeriodLocks]=useState<PeriodLock[]>([])
  const [closeReadiness,setCloseReadiness]=useState<CloseReadiness|null>(null);const [closeChecks,setCloseChecks]=useState<Record<string,boolean>>({});const [closeActor,setCloseActor]=useState(()=>localStorage.getItem('workos-close-actor')||'');const [closeError,setCloseError]=useState('');const [closeBusy,setCloseBusy]=useState(false)
  const [operatingReport,setOperatingReport]=useState<OperatingReport|null>(null)
  const [journalEntries,setJournalEntries]=useState<JournalEntry[]>([])
  const [apiOnline, setApiOnline] = useState(false)
  const [lastRefreshAt,setLastRefreshAt]=useState<Date|null>(null)
  const copy = moduleCopy[active]
  async function refreshData() {
    try {
      const [health, inv, movement, po, op, expenseRows, projectRows, samples, bike, bikeCostRows, bikeSaleRows, bank, invoice, periods, operating, journals, rules,safety] = await Promise.all([fetch('/api/health'),fetch('/api/inventory'),fetch('/api/movements'),fetch('/api/purchases'),fetch('/api/receivables-payables'),fetch('/api/expenses'),fetch('/api/projects'),fetch('/api/projects/samples'),fetch('/api/bike/orders'),fetch('/api/bike/landed-costs'),fetch('/api/bike/sales'),fetch('/api/bank/transactions'),fetch('/api/invoices'),fetch('/api/periods'),fetch(`/api/reports/operating?period=${currentPeriod}`),fetch('/api/journals'),fetch('/api/packaging-rules'),fetch('/api/inventory/safety-stock')])
      if (![health,inv,movement,po,op,expenseRows,projectRows,samples,bike,bikeCostRows,bikeSaleRows,bank,invoice,periods,operating,journals,rules,safety].every(r=>r.ok)) throw new Error('本地 API 暂不可用')
      setInventory(await inv.json());setSafetyStocks(await safety.json());setInventoryMovements(await movement.json());setPurchases(await po.json());setOpenItems(await op.json());setExpenses(await expenseRows.json());setProjects(await projectRows.json());setSampleDispatches(await samples.json());setBikeOrders(await bike.json());setBikeCosts(await bikeCostRows.json());setBikeSales(await bikeSaleRows.json());setBankRows(await bank.json());setInvoices(await invoice.json());setPeriodLocks(await periods.json());setOperatingReport(await operating.json());setJournalEntries(await journals.json());setPackagingRules(await rules.json());setLastRefreshAt(new Date());setApiOnline(true)
    } catch { setApiOnline(false) }
  }
  useEffect(() => { void refreshData() }, [])
  // 任何入口改变了当前模块/子页（含业务代码里的 setTab / navigate），都自动补进标签栏
  useEffect(() => {
    const key = `${active}|${tab}`
    setOpenTabs(prev => prev.some(x => x.key === key) ? prev : [...prev, { key, module: active, tab, label: moduleCopy[active].tabs[tabIndexOf(tab)] }])
  }, [active, tab])
  const isCurrentPeriodClosed = periodLocks.some(row=>row.period===currentPeriod)
  async function openPeriodCloseReview(){if(isCurrentPeriodClosed)return;setCloseReadiness(null);setCloseError('');setCloseChecks({});setCloseBusy(true);try{const response=await fetch(`/api/periods/close-readiness?period=${currentPeriod}`);const data=await response.json();if(!response.ok)throw new Error(data.error||'无法读取关账检查');setCloseReadiness(data)}catch(error){setCloseError(error instanceof Error?error.message:'关账检查失败')}finally{setCloseBusy(false)}}
  async function closeCurrentPeriod(){if(!closeReadiness?.can_close||!closeActor.trim())return;const reviewed=closeReadiness.checks_required.map(item=>item.key);if(reviewed.some(key=>!closeChecks[key]))return;setCloseBusy(true);setCloseError('');try{const response=await fetch('/api/periods/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({period:currentPeriod,closed_by:closeActor.trim(),reviewed_checks:reviewed})});const data=await response.json();if(!response.ok)throw new Error(data.error||'关账失败');setCloseReadiness(null);await refreshData()}catch(error){setCloseError(error instanceof Error?error.message:'关账失败')}finally{setCloseBusy(false)}}
  function openCloseReviewItem(action:CloseAction){setCloseReadiness(null);if(action==='inventory'){navigate('coffee');return}setFinanceFocus(action);navigate('finance')}
  const inventoryValue = inventory.filter(row => row.currency === 'CNY').reduce((sum, row) => sum + Number(row.value), 0)
  const cnyReceivables = openItems.filter(row=>row.currency==='CNY'&&row.direction==='receivable').reduce((sum,row)=>sum+Number(row.original_amount)-Number(row.settled_amount),0)
  const cnyPayables = openItems.filter(row=>row.currency==='CNY'&&row.direction==='payable').reduce((sum,row)=>sum+Number(row.original_amount)-Number(row.settled_amount),0)
  const today = new Date().toISOString().slice(0,10)
  const todoGroups = [
    {key:'bank',label:'银行流水待认领',detail:'尚有未分配余额的流水',count:bankRows.filter(row=>Number(row.remaining_amount)>0).length,icon:ArrowDownLeft,tint:'amber'},
    {key:'fx',label:'外币账面汇率待复核',detail:'流水或往来余额缺少 CNY 估值',count:bankRows.filter(row=>row.currency!=='CNY'&&!row.base_amount_cny).length+openItems.filter(row=>row.currency!=='CNY'&&!row.original_amount_cny).length,icon:Activity,tint:'blue'},
    {key:'overdue',label:'逾期应收 / 应付',detail:'到期日已过且仍有未结余额',count:openItems.filter(row=>Boolean(row.due_on)&&row.due_on!<=today&&Number(row.original_amount)>Number(row.settled_amount)).length,icon:CalendarDays,tint:'red'},
    {key:'tax',label:'发票税务状态待核实',detail:'尚未登记税务用途结论',count:invoices.filter(invoice=>invoice.tax_status==='pending').length,icon:FileCheck2,tint:'amber'},
  ].filter(task=>task.count>0)
  const todoCount = todoGroups.reduce((sum,task)=>sum+task.count,0)
  const foreignInventoryCurrencies = [...new Set(inventory.map(row => row.currency).filter(currency => currency !== 'CNY'))]
  const inventoryCount = inventory.reduce((sum, row) => sum + row.quantity, 0)
  const activityItems = useMemo<ActivityItem[]>(()=>{
    const purchaseEvents:ActivityItem[]=purchases.map(row=>({id:`purchase:${row.id}`,icon:Coffee,tint:'blue',title:`采购单 ${row.number}`,detail:`${row.supplier} · ${row.sku} · 采购 ${row.ordered_qty} / 到货 ${row.received_qty}`,time:(row.created_at||row.receipts.at(-1)?.received_on||'').slice(0,10),amount:`${row.currency} ${row.order_amount}`,state:row.received_qty>=row.ordered_qty?'已到齐':row.received_qty>0?'部分到货':'待到货',stateColor:row.received_qty>=row.ordered_qty?'green':'amber'}))
    const expenseEvents:ActivityItem[]=expenses.map(row=>({id:`expense:${row.id}`,icon:WalletCards,tint:'amber',title:`经营费用 · ${row.counterparty}`,detail:`${row.category} · ${row.memo||row.source_key}`,time:row.incurred_on,amount:`${row.currency} ${row.amount}`,state:'已确认',stateColor:'green'}))
    const bankEvents:ActivityItem[]=bankRows.map(row=>{const remaining=Number(row.remaining_amount);const allocated=Number(row.allocated_amount);return{id:`bank:${row.id}`,icon:row.direction==='in'?ArrowDownLeft:ArrowUpRight,tint:row.direction==='in'?'green':'amber',title:row.direction==='in'?'银行收款':'银行付款',detail:`${row.account_name} · ${row.bank_reference||row.description||'无摘要'}`,time:row.transaction_on,amount:`${row.currency} ${row.amount}`,state:remaining<=0?'已全部分配':allocated>0?'部分分配':'待认领',stateColor:remaining<=0?'green':allocated>0?'blue':'amber'}})
    const movementGroups=new Map<string,{row:InventoryMovement;quantity:number}>()
    for(const row of inventoryMovements){const key=`${row.source_type}:${row.source_id}:${row.sku}:${row.movement_type}`;const existing=movementGroups.get(key);if(existing)existing.quantity+=row.quantity;else movementGroups.set(key,{row,quantity:row.quantity})}
    const movementEvents:ActivityItem[]=[...movementGroups.values()].map(({row,quantity})=>{const labels:Record<string,string>={receipt:'库存收货',sale:'销售出库',sale_return:'销售退货入库',sample_dispatch:'展会样品发出',sample_return:'展会样品归还',adjustment_gain:'盘点盘盈',adjustment_loss:'盘点盘亏'};const label=labels[row.movement_type]||row.movement_type;const sources:Record<string,string>={purchase_receipt:'采购收货',sale:'销售单',sale_return:'销售退货',exhibition_sample:'展会样品',exhibition_sample_return:'展会样品归还',inventory_adjustment:'库存盘点'};return{id:`movement:${row.source_type}:${row.source_id}:${row.sku}:${row.movement_type}`,icon:quantity<0?ArrowUpRight:PackageIcon,tint:quantity<0?'amber':'green',title:label,detail:`${row.sku} · ${sources[row.source_type]||row.source_type} · ${row.source_id.slice(0,12)}`,time:(row.effective_on||row.created_at).slice(0,10),amount:`${quantity>0?'+':''}${quantity} 件`,state:'已过账',stateColor:'green'}})
    return[...purchaseEvents,...expenseEvents,...bankEvents,...movementEvents].filter(item=>item.time).sort((a,b)=>b.time.localeCompare(a.time)||a.id.localeCompare(b.id)).slice(0,100)
  },[purchases,expenses,bankRows,inventoryMovements])
  const visibleItems = useMemo(() => activityItems.filter(item => `${item.title} ${item.detail} ${item.state} ${item.amount}`.toLowerCase().includes(query.toLowerCase())), [activityItems,query])

  function navigate(id: Module) { openPage(id, 'overview') }

  return <div className="fx-shell">
    <header className="fx-topbar">
      <button className="fx-brand" onClick={() => openPage('overview','overview')} aria-label="回到经营总览"><span className="fx-logo">🤝</span><span className="fx-brandname">workOS · 经营工作台</span></button>
      <div className="fx-brandpick" title="当前本地账套"><span className="fx-bp-logo">🏷</span><span className="fx-bp-name">本地工作账套</span><span className="fx-bp-arrow">▾</span></div>
      <nav className="fx-primary" aria-label="一级导航">
        {modules.map(item => <button key={item.id} className={`fx-pitem ${active === item.id ? 'active' : ''}`} onClick={() => openPage(item.id, 'overview')}><span className="fx-ic">{moduleIconEmoji[item.id]}</span><span>{item.label}</span></button>)}
      </nav>
      <div className="fx-topright">
        <span className="fx-ver">v<b>0.1</b></span>
        <button className="fx-iconbtn" title="刷新当前页" onClick={() => void refreshData()}>↻</button>
        <button className="fx-iconbtn fx-notif" title={`待办 ${todoCount} 项`} onClick={()=>openPage('finance','actions')}>🔔{apiOnline&&todoCount>0&&<i className="fx-notif-dot">{todoCount>99?'99+':todoCount}</i>}</button>
        <button className="fx-avatar" title="账期：账套已就绪">J</button>
      </div>
    </header>

    <div className="fx-body">
      <aside className={`fx-side ${sideOpen ? '' : 'hidden'}`}>
        <div className="fx-sideInner">
          <div className="fx-sideTitle">{copy.title} / 菜单</div>
          <nav className="fx-secondary">
            {copy.tabs.map((label, i) => <button key={label} className={`fx-sitem ${i === tabIndexOf(tab) ? 'active' : ''}`} onClick={() => openPage(active, tabValueOf(i))}><span className="fx-ic">{tabIconEmoji[active]?.[i] || '•'}</span><span className="fx-txt">{label}</span></button>)}
          </nav>
        </div>
      </aside>

      <main className="fx-main">
        <div className="fx-tabbar">
          <button className="fx-menutoggle" title="展开 / 收起左侧菜单" onClick={() => setSideOpen(!sideOpen)}>☰</button>
          <div className="fx-tabstrip">
            {openTabs.map(item => <div key={item.key} className={`fx-tab ${active === item.module && tab === item.tab ? 'active' : ''}`} onClick={() => activateTab(item)}><span>{item.label}</span><button className="fx-x" title="关闭标签" onClick={e => closeTab(item.key, e)}>✕</button></div>)}
          </div>
          <div className="fx-tabtools">
            <button className="fx-iconbtn" title="刷新当前页" onClick={() => void refreshData()}>↻</button>
            <button className="fx-iconbtn" title="关闭其他标签" onClick={closeAllTabs}>✕</button>
          </div>
        </div>
        <div className="fx-frames">
          <div className="fx-frame active">
            <div className="main-content">
      <div className="breadcrumb"><span>工作空间</span><span className="crumb-slash">/</span><span>{active === 'overview' ? '经营总览' : modules.find(item => item.id === active)?.label}</span><span className="breadcrumb-right"><ShieldCheck size={13}/> 本地工作账套</span></div>
      <section className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line"/>{copy.eyebrow}</div><h1>{copy.title}</h1><p className="welcome-desc">{copy.desc}</p></div><button className="primary-button" onClick={() => setDrawer(true)}><Plus size={17}/> 新建业务单据</button></section>

      <div className="subnav-row"><div className="subnav">{copy.tabs.map((label, i) => <button key={label} className={i === (tab === 'overview' ? 0 : tab === 'activity' ? 1 : 2) ? 'active' : ''} onClick={() => setTab(i === 0 ? 'overview' : i === 1 ? 'activity' : 'actions')}>{label}{label === '待我处理' && apiOnline && <span className="tab-count">{todoCount}</span>}</button>)}</div><div className="date-filter"><CalendarDays size={15}/> 本月 <ChevronDown size={13}/></div></div>

      {active === 'coffee' ? <CoffeeWorkspace inventory={inventory} safetyStocks={safetyStocks} movements={inventoryMovements} purchases={purchases} packagingRules={packagingRules} apiOnline={apiOnline} refresh={refreshData} quickCreate={quickCreate}/> : active === 'bike' ? <BikeWorkspace orders={bikeOrders} costs={bikeCosts} sales={bikeSales} tab={tab} refresh={refreshData}/> : active === 'finance' ? <FinanceWorkspace projects={projects} openItems={openItems} expenses={expenses} bankRows={bankRows} invoices={invoices} journalEntries={journalEntries} operatingReport={operatingReport} currentPeriod={currentPeriod} refresh={refreshData} focus={financeFocus}/> : active==='exhibition'?<ExhibitionWorkspace projects={projects} expenses={expenses} inventory={inventory} packagingRules={packagingRules} sampleDispatches={sampleDispatches} tab={tab} refresh={refreshData}/>: active === 'overview' ? <>
        <section className="metric-grid" aria-label="经营关键指标">
          <Metric title="本月销售收入" value={apiOnline&&operatingReport?`${operatingReport.currency} ${Number(operatingReport.sales_revenue).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`:'—'} change={operatingReport?.period===currentPeriod?'按本期已过账分录':'等待本地 API 连接'} trend={apiOnline?'neutral':'warning'} icon={ArrowUpRight} caption="权责发生制确认的销售收入" chart={[]} />
          <Metric title="本月销售毛利" value={apiOnline&&operatingReport?`${operatingReport.currency} ${Number(operatingReport.gross_profit).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`:'—'} change={operatingReport?.period===currentPeriod?'收入减 FIFO 销售成本':'等待本地 API 连接'} trend={apiOnline?'neutral':'warning'} icon={Activity} caption="费用按已登记事实计算；完整性需在财务中心核对" chart={[]} tone="green" />
          <Metric title="待收 / 待付（人民币）" value={apiOnline ? `¥ ${cnyReceivables.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})} / ¥ ${cnyPayables.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}` : '—'} change={apiOnline ? '顺序为应收 / 应付 · 不含外币' : '等待本地 API 连接'} trend={apiOnline?'neutral':'warning'} icon={ArrowDownLeft} caption={openItems.some(x=>x.currency!=='CNY')?'外币余额请在财务中心按原币查看':'应收应付未结余额'} chart={[]} tone="orange" />
          <Metric title="库存资产（人民币）" value={apiOnline ? `¥ ${inventoryValue.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}` : '—'} change={apiOnline ? `${inventoryCount} 件 · ${inventory.length} 个 SKU/币种批次` : '启动本地 API 以查看'} trend={apiOnline ? 'neutral' : 'warning'} icon={PackageIcon} caption={foreignInventoryCurrencies.length ? `外币库存未折算：${foreignInventoryCurrencies.join('、')}` : 'FIFO 库存层剩余成本 · 不含待认证税额'} chart={[]} tone="purple" />
        </section>

        <section className="middle-grid">
          <div className="panel trend-panel"><div className="panel-heading"><div><h2>经营收入趋势</h2><p>近六个月 · 按已过账凭证统计</p></div></div><OperatingTrendChart period={currentPeriod} apiOnline={apiOnline}/></div>
          <div className="panel breakdown-panel"><div className="panel-heading"><div><h2>业务线贡献</h2><p>本月已过账销售净收入</p></div></div><BusinessLineContribution period={currentPeriod} apiOnline={apiOnline}/><button className="text-link" onClick={() => navigate('finance')}>查看经营报表 <ArrowRight size={14}/></button></div>
        </section>

        <section className="bottom-grid"><div className="panel activity-panel"><div className="panel-heading"><div className="activity-title"><div><h2>近期业务动态</h2><p>来自本地采购、库存、费用与银行流水</p></div><span className="activity-badge">{apiOnline?`${activityItems.length} 条`:'本地业务数据'}</span></div><button className="text-link" onClick={() => setTab('activity')}>全部动态 <ArrowRight size={14}/></button></div><div className="table-tools"><label className="search-box"><Search size={14}/><input placeholder="搜索单据、供应商…" value={query} onChange={e => setQuery(e.target.value)}/><kbd>⌘ K</kbd></label><span className="table-count">{visibleItems.length} 条</span></div><div className="activity-table"><div className="table-header"><span>业务事项</span><span>时间</span><span>金额</span><span>状态</span><span/></div>{visibleItems.length === 0 ? <div className="empty-inline">{activityItems.length?'没有匹配的业务动态。':'尚无已登记采购、收货、费用或银行流水。'}</div> : visibleItems.slice(0,8).map((item, i) => <div className="table-row" key={item.id}><div className="activity-name"><span className={`activity-icon ${item.tint}`}><item.icon size={15}/></span><span><strong>{item.title}</strong><small>{item.detail}</small></span></div><span className="time-cell">{item.time}</span><span className="amount-cell">{item.amount}</span><span><i className={`status-pill ${item.stateColor}`}>{item.state}</i></span><button className="row-more" aria-label={`打开${item.title}`} onClick={() => setDrawer(true)}><MoreHorizontal size={17}/></button>{i < Math.min(visibleItems.length,8) - 1 && <span className="row-rule"/>}</div>)}</div><button className="mobile-all" onClick={() => setTab('activity')}>查看全部业务动态 <ArrowRight size={14}/></button></div>
          <div className="panel todo-panel"><div className="panel-heading"><div><h2>待我处理</h2><p>{apiOnline?'根据本地未结单据实时汇总':'连接本地 API 后读取待办'}</p></div><button className="todo-total">{apiOnline?todoCount:'—'}</button></div>{!apiOnline?<div className="empty-state compact"><Activity size={20}/><strong>待办暂不可用</strong><span>本地 API 离线，无法读取业务状态。</span></div>:todoGroups.length===0?<div className="empty-state compact"><Check size={20}/><strong>当前没有待办</strong><span>银行流水、汇率、到期往来和税务状态均无待处理项。</span></div>:<div className="todo-list">{todoGroups.map(task=><button className="todo-item" key={task.key} onClick={()=>{navigate('finance');setTab('actions')}}><span className={`todo-icon ${task.tint}`}><task.icon size={14}/></span><span className="todo-copy"><strong>{task.label}</strong><small>{task.detail}</small></span><span className="todo-count">{task.count} 项</span><ArrowRight size={13} className="todo-arrow"/></button>)}</div>}<button className="todo-link" onClick={() => { navigate('finance'); setTab('actions') }}>打开财务核算中心 <ArrowRight size={14}/></button></div></section>
        <footer className="footer-note"><span><Sparkles size={13}/> 经营数字以业务确认和月结结果为准</span><span>{apiOnline?lastRefreshAt?`本地数据刷新于 ${lastRefreshAt.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`:'已连接本地 API':lastRefreshAt?`本地 API 离线 · 上次刷新 ${lastRefreshAt.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`:'本地 API 离线'} <i className={`refresh-dot ${apiOnline?'':'offline'}`}/></span></footer>
      </> : tab==='actions'?<section className="panel todo-workspace"><div className="panel-heading"><div><h2>待我处理</h2><p>任务由当前本地银行流水、往来余额和发票状态计算。</p></div><button className="todo-total">{apiOnline?todoCount:'—'}</button></div>{!apiOnline?<div className="empty-state"><Activity size={22}/><strong>待办暂不可用</strong><span>本地 API 离线。</span></div>:todoGroups.length===0?<div className="empty-state"><Check size={22}/><strong>当前没有待办</strong><span>待认领流水、汇率复核、逾期往来和税务状态均为零。</span></div>:<div className="todo-list">{todoGroups.map(task=><button className="todo-item" key={task.key} onClick={()=>{setFinanceFocus(task.key==='fx'||task.key==='overdue'?'items':task.key==='tax'?'invoices':'bank');navigate('finance')}}><span className={`todo-icon ${task.tint}`}><task.icon size={15}/></span><span className="todo-copy"><strong>{task.label}</strong><small>{task.detail}</small></span><span className="todo-count">{task.count} 项</span><ArrowRight size={14} className="todo-arrow"/></button>)}</div>}</section>:tab==='activity'?<ActivityTimeline items={visibleItems} query={query} onQueryChange={setQuery}/>:<section className="panel tab-placeholder"><span className="placeholder-icon"><Activity size={21}/></span><h2>{copy.tabs[1]}</h2><p>当前页面尚无可展示内容。</p><button className="secondary-button" onClick={() => setTab('overview')}>回到经营总览</button></section>}
            </div>
          </div>
        </div>
      </main>
    </div>

    {(closeReadiness||closeBusy||closeError)&&<div className="modal-backdrop"><section className="period-close-modal" role="dialog" aria-modal="true" aria-labelledby="period-close-title"><div className="panel-heading"><div><h2 id="period-close-title">{currentPeriod} 关账检查</h2><p>系统检查可验证的账务异常；其余核对项由关账人确认并留存。关账人姓名为手工填写，尚未接入身份认证。</p></div><button className="icon-button" onClick={()=>{setCloseReadiness(null);setCloseError('')}} aria-label="关闭"><X size={18}/></button></div>{closeBusy&&!closeReadiness?<div className="empty-inline">正在检查本期账务…</div>:closeError?<div className="form-error">{closeError}</div>:closeReadiness&&<><div className="close-readiness-summary"><span>本期凭证 {closeReadiness.journal_count} 张</span><span>银行流水 {closeReadiness.bank_rows} 笔</span><span>登记账户 {closeReadiness.registered_bank_accounts} 个 · 未核平 {closeReadiness.unreconciled_bank_accounts} 个</span><span>账户清单 {closeReadiness.bank_account_list_unconfirmed?'待确认':'已确认'}</span><span>未分类流水分配 {closeReadiness.unclassified_bank_allocations} 笔</span><span>待复核税务状态发票 {closeReadiness.pending_tax_invoices} 张</span></div><CloseReviewEvidence readiness={closeReadiness} onOpen={openCloseReviewItem}/><div className="close-review-list">{closeReadiness.checks_required.map(item=><label key={item.key}><input type="checkbox" checked={Boolean(closeChecks[item.key])} onChange={event=>setCloseChecks({...closeChecks,[item.key]:event.target.checked})}/><span><strong>{item.label}</strong><small>{item.detail}</small></span></label>)}</div><label className="close-operator">关账人姓名（手工填写）<input value={closeActor} onChange={event=>{setCloseActor(event.target.value);localStorage.setItem('workos-close-actor',event.target.value)}} placeholder="填写实际复核人" required/></label><p className="report-caveat">费用完整性及外部数据对账仍依赖人工复核；确认表示你已完成上述检查。未分配流水、银行未核平和缺少汇率的外币余额会阻止关账；已暂挂待分类的流水须核对并在复核清单中确认。</p></>}{closeReadiness&&<div className="close-modal-actions"><button className="secondary-button" onClick={()=>setCloseReadiness(null)}>返回</button><button className="primary-button" disabled={closeBusy||!closeActor.trim()||!closeReadiness.can_close||closeReadiness.checks_required.some(item=>!closeChecks[item.key])} onClick={()=>void closeCurrentPeriod()}>{closeBusy?'正在关账…':closeReadiness.can_close?'确认并关账':'先处理阻断项'}</button></div>}</section></div>}

    {drawer && <div className="drawer-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setDrawer(false) }}><aside className="drawer"><div className="drawer-head"><div><span className="eyebrow">QUICK CREATE</span><h2>新建业务单据</h2><p>选择单据类型，快速录入一条业务事实。</p></div><button className="icon-button" onClick={() => setDrawer(false)} aria-label="关闭"><X size={18}/></button></div><div className="drawer-section-label">常用单据</div><div className="create-options"><CreateOption icon={Coffee} title="咖啡采购单" desc="登记采购数量与凭据金额，再记录到货数量" onClick={() => { setDrawer(false); setQuickCreate({kind:'purchase',requestId:crypto.randomUUID()}); setActive('coffee'); setTab('overview') }}/><CreateOption icon={FileSpreadsheet} title="销售数据导入" desc="打开销售导入与列映射页面" onClick={() => { setDrawer(false); setQuickCreate({kind:'sales',requestId:crypto.randomUUID()}); setActive('coffee'); setTab('overview') }}/><CreateOption icon={WalletCards} title="经营费用" desc="按发生日期登记费用并形成应付" onClick={() => { setDrawer(false); setFinanceFocus('expenses'); setActive('finance'); setTab('overview') }}/><CreateOption icon={BriefcaseBusiness} title="展会项目" desc="选择或新建展会项目后登记预算与费用" onClick={() => { setDrawer(false); setActive('exhibition'); setTab('overview') }}/></div><div className="drawer-foot"><CircleHelp size={15}/> 单据确认后将保留完整操作记录。</div></aside></div>}
  </div>
}

function BusinessLineContribution({period,apiOnline}:{period:string;apiOnline:boolean}){
  const [rows,setRows]=useState<{key:string;label:string;revenue:number}[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('')
  useEffect(()=>{if(!apiOnline){setRows([]);return}let live=true;const lines=[['coffee','咖啡'],['bike','自行车'],['exhibition','展会'],['corporate','公司其他'],['unassigned','未归属']] as const;setLoading(true);setError('');Promise.all(lines.map(async([key,label])=>{const response=await fetch(`/api/reports/operating?period=${period}&business_line=${key}`);const data=await response.json();if(!response.ok)throw new Error(data.error||`无法读取${label}业务收入`);return{key,label,revenue:Number((data as OperatingReport).sales_revenue)}})).then(data=>{if(live)setRows(data)}).catch(reason=>{if(live)setError(reason instanceof Error?reason.message:'本地 API 不可用')}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[period,apiOnline])
  if(!apiOnline)return <div className="breakdown-empty">连接本地 API 后显示业务线贡献。</div>
  if(loading&&!rows.length)return <div className="breakdown-empty">正在读取本月业务线收入…</div>
  if(error)return <div className="breakdown-empty">{error}</div>
  const total=rows.reduce((sum,row)=>sum+row.revenue,0);const hasData=rows.some(row=>row.revenue!==0)
  if(!hasData)return <div className="breakdown-empty">本月尚无已过账销售收入。</div>
  return <div className="business-line-list">{rows.filter(row=>row.revenue!==0).map(row=>{const share=total>0?Math.max(0,row.revenue/total*100):0;return <div className="business-line-item" key={row.key}><div className="business-line-head"><strong>{row.label}</strong><span>CNY {row.revenue.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}{total>0?` · ${share.toFixed(1)}%`:''}</span></div><div className="business-line-track"><i style={{width:`${Math.min(100,share)}%`}}/></div></div>})}{total<=0&&<small className="business-line-note">净收入合计不大于零，暂不计算正向占比。</small>}</div>
}

function OperatingTrendChart({period,apiOnline}:{period:string;apiOnline:boolean}){
  const [rows,setRows]=useState<OperatingReport[]>([]);const [loading,setLoading]=useState(false);const [error,setError]=useState('')
  useEffect(()=>{if(!apiOnline){setRows([]);return}let live=true;const [year,month]=period.split('-').map(Number);const periods=Array.from({length:6},(_,index)=>{const date=new Date(year,month-1-(5-index),1);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`});setLoading(true);setError('');Promise.all(periods.map(async value=>{const response=await fetch(`/api/reports/operating?period=${value}`);const data=await response.json();if(!response.ok)throw new Error(data.error||`无法读取 ${value} 经营报表`);return data as OperatingReport})).then(data=>{if(live)setRows(data)}).catch(reason=>{if(live)setError(reason instanceof Error?reason.message:'本地 API 不可用')}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[period,apiOnline])
  if(!apiOnline)return <div className="chart-empty">连接本地 API 后显示收入与销售成本趋势。</div>
  if(loading&&!rows.length)return <div className="chart-empty">正在读取近六个月已过账数据…</div>
  if(error)return <div className="chart-empty">{error}</div>
  if(!rows.some(row=>Number(row.sales_revenue)!==0||Number(row.cost_of_goods_sold)!==0))return <div className="chart-empty">近六个月尚无已过账销售收入或销售成本。</div>
  const maxValue=Math.max(1,...rows.flatMap(row=>[Math.abs(Number(row.sales_revenue)),Math.abs(Number(row.cost_of_goods_sold))]))
  return <div className="trend-chart-wrap"><div className="trend-legend"><span><i className="revenue"/>销售收入</span><span><i className="cost"/>销售成本</span><span><i className="negative"/>负值</span></div><div className="trend-chart" role="img" aria-label="近六个月销售收入和销售成本趋势，正值向上，负值向下">{rows.map(row=>{const revenue=Number(row.sales_revenue);const cogs=Number(row.cost_of_goods_sold);const height=(value:number)=>`${Math.abs(value)===0?0:Math.max(2,Math.abs(value)/maxValue*46)}%`;return <div className="trend-month" key={row.period}><div className="trend-bars"><span className={`trend-bar revenue ${revenue<0?'negative':''}`} style={{height:height(revenue)}} title={`${row.period} 销售收入 CNY ${row.sales_revenue}`}/><span className={`trend-bar cost ${cogs<0?'negative':''}`} style={{height:height(cogs)}} title={`${row.period} 销售成本 CNY ${row.cost_of_goods_sold}`}/></div><small>{row.period.slice(5)}月</small></div>})}</div><div className="trend-latest">{rows.at(-1)?.period} · 收入 CNY {rows.at(-1)?.sales_revenue} · 成本 CNY {rows.at(-1)?.cost_of_goods_sold}</div></div>
}

function ActivityTimeline({items,query,onQueryChange}:{items:ActivityItem[];query:string;onQueryChange:(value:string)=>void}){
  return <section className="panel activity-panel"><div className="panel-heading"><div><h2>全部业务动态</h2><p>按发生日期倒序，来自本地采购、库存、费用与银行流水。</p></div><span className="table-count">{items.length} 条</span></div><div className="table-tools"><label className="search-box"><Search size={14}/><input placeholder="搜索单据、供应商、摘要…" value={query} onChange={event=>onQueryChange(event.target.value)}/></label></div><div className="activity-table"><div className="table-header"><span>业务事项</span><span>时间</span><span>金额 / 数量</span><span>状态</span><span/></div>{items.length===0?<div className="empty-inline">当前没有匹配的本地业务动态。</div>:items.map(item=><div className="table-row" key={item.id}><div className="activity-name"><span className={`activity-icon ${item.tint}`}><item.icon size={15}/></span><span><strong>{item.title}</strong><small>{item.detail}</small></span></div><span className="time-cell">{item.time}</span><span className="amount-cell">{item.amount}</span><span><i className={`status-pill ${item.stateColor}`}>{item.state}</i></span><span/></div>)}</div></section>
}

function CloseReviewEvidence({readiness,onOpen}:{readiness:CloseReadiness;onOpen:(action:CloseAction)=>void}){
  const statusLabel={blocking:'需处理',attention:'待关注',clear:'无异常',manual:'人工核对'} as const
  return <div className="close-evidence-list">{readiness.blockers.map(item=><div className="close-blocker-row" key={item.key}><span>{item.label}：{item.count} 项</span><button className="text-link" onClick={()=>onOpen(item.action)}>前往处理 <ArrowRight size={13}/></button></div>)}{readiness.review_items.map(item=><article className={`close-evidence-item ${item.status}`} key={item.key}><div className="close-evidence-copy"><div><strong>{item.label}</strong><span className={`close-status ${item.status}`}>{statusLabel[item.status]}</span></div><p>{item.summary}</p>{item.details?.map((detail,index)=><small key={`${item.key}:${index}`}>{detail.date||detail.source_type||''}{detail.reference?` · ${detail.reference}`:''}{detail.counterparty?` · ${detail.counterparty}`:''}{detail.description?` · ${detail.description}`:''}{detail.currency?` · ${detail.currency} ${detail.remaining||detail.outstanding||''}`:''}</small>)}{item.balances_by_currency&&Object.keys(item.balances_by_currency).length>0&&<small>当前库存账面：{Object.entries(item.balances_by_currency).map(([currency,value])=>`${currency} ${value}`).join(' · ')}</small>}</div><button className="secondary-button" onClick={()=>onOpen(item.action)}>{item.action_label}</button></article>)}</div>
}

function CoffeeWorkspace({ inventory, safetyStocks, movements, purchases, packagingRules, apiOnline, refresh, quickCreate }: { inventory: InventoryRow[]; safetyStocks:SafetyStockRow[]; movements:InventoryMovement[]; purchases: PurchaseRow[]; packagingRules:PackagingRule[]; apiOnline: boolean; refresh: () => Promise<void>; quickCreate:{kind:'purchase'|'sales';requestId:string}|null }) {
  const [subtab, setSubtab] = useState<'purchases'|'stock'|'sales'|'rules'|'sales-returns'|'analysis'>('purchases')
  useEffect(()=>{if(!quickCreate)return;setSubtab(quickCreate.kind==='purchase'?'purchases':'sales');requestAnimationFrame(()=>{const target=document.querySelector(quickCreate.kind==='purchase'?'.purchase-form input[name="number"]':'.sales-import input');if(target instanceof HTMLElement){target.scrollIntoView({behavior:'smooth',block:'center'});target.focus({preventScroll:true})}})},[quickCreate?.requestId])
  const [purchaseFilter,setPurchaseFilter]=useState<'all'|'finished_goods'|'packaging'|'in_transit'>('all')
  const visiblePurchases=purchases.filter(po=>purchaseFilter==='all'||(purchaseFilter==='in_transit'?po.received_qty<po.ordered_qty:po.item_type===purchaseFilter))
  const [error, setError] = useState('')
  const [receiveError, setReceiveError] = useState('')
  const [busy, setBusy] = useState(false)
  const [receiving, setReceiving] = useState<PurchaseRow|null>(null)
  const [editingReceipt,setEditingReceipt]=useState<{purchase:PurchaseRow;receipt:PurchaseReceiptRow}|null>(null)
  const [receiveSourceKey,setReceiveSourceKey]=useState('')
  const [editReceiptError,setEditReceiptError]=useState('')
  const [purchaseFile,setPurchaseFile]=useState<File|null>(null)
  async function createPurchase(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(''); setBusy(true)
    const target = event.currentTarget
    const form = new FormData(target)
    const entries = Object.fromEntries(form.entries())
    const quantity=Number(entries.quantity),documentAmount=Number(entries.document_amount)
    const suppliedUnitCost=String(entries.unit_cost||'').trim()
    const data = {...entries, quantity, unit_cost:suppliedUnitCost||((quantity>0&&Number.isFinite(documentAmount)?documentAmount/quantity:0).toFixed(8))}
    try {
      if(!purchaseFile)throw new Error('请上传采购单或合同原件，归档成功后再创建采购单')
      const evidence=await archiveOriginal(purchaseFile,'purchase',new Date().toLocaleDateString('sv-SE').slice(0,7),'coffee.purchase')
      const response = await fetch('/api/purchases', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({...data,archive_file_id:evidence.id}) })
      const result = await response.json(); if (!response.ok) throw new Error(result.error || '采购原件已归档，但采购单未创建：'+(result.error||'保存失败'))
      target.reset();setPurchaseFile(null); await refresh()
    } catch (e) { setError(e instanceof Error ? e.message : '本地 API 未连接') } finally { setBusy(false) }
  }
  async function receivePurchase(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!receiving)return;const target=event.currentTarget;const form=new FormData(target);setReceiveError('');setBusy(true);try{const response=await fetch(`/api/purchases/${receiving.id}/receive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(form.entries()))});const data=await response.json();if(!response.ok)throw new Error(data.error||'收货登记失败');target.reset();setReceiving(null);await refresh()}catch(e){setReceiveError(e instanceof Error?e.message:'本地 API 未连接')}finally{setBusy(false)}}
  async function editPurchaseReceipt(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!editingReceipt)return;const values=Object.fromEntries(new FormData(event.currentTarget).entries());setEditReceiptError('');setBusy(true);try{const response=await fetch(`/api/purchase-receipts/${editingReceipt.receipt.id}/edit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,changed_by:'local-unverified',action_key:crypto.randomUUID()})});const result=await response.json();if(!response.ok)throw new Error(result.error||'到货记录修改失败');setEditingReceipt(null);await refresh()}catch(error){setEditReceiptError(error instanceof Error?error.message:'本地 API 未连接')}finally{setBusy(false)}}
  return <section className="coffee-workspace"><div className="workspace-tabs"><button className={subtab==='purchases'?'active':''} onClick={()=>setSubtab('purchases')}>采购管理</button><button className={subtab==='stock'?'active':''} onClick={()=>setSubtab('stock')}>库存管理 <span>{inventory.length}</span></button><button className={subtab==='sales'?'active':''} onClick={()=>setSubtab('sales')}>销售导入</button><button className={subtab==='rules'?'active':''} onClick={()=>setSubtab('rules')}>SKU 包装规则</button><button className={subtab==='sales-returns'?'active':''} onClick={()=>setSubtab('sales-returns')}>销售退货</button><button className={subtab==='analysis'?'active':''} onClick={()=>setSubtab('analysis')}>经营分析</button><span className={apiOnline?'connection ok':'connection'}>{apiOnline?'本地数据库已连接':'等待本地 API 连接'}</span></div>
  {subtab==='analysis'?<CoffeeMarginAnalysis/>:subtab==='sales-returns'?<SalesReturnsWorkspace refresh={refresh}/>:subtab==='sales' ? <SalesImport inventory={inventory} packagingRules={packagingRules} refresh={refresh}/> : subtab==='rules' ? <PackagingRulesWorkspace rules={packagingRules} refresh={refresh}/> : subtab==='purchases' ? <div className="coffee-columns"><div className="panel purchase-list"><div className="panel-heading"><div><h2>咖啡采购单</h2><p>记录采购与到货数量，按凭据金额核对到货金额。</p></div><span className="table-count">{visiblePurchases.length} / {purchases.length} 张</span></div><div className="purchase-filters">{([{key:'all',label:'全部'},{key:'finished_goods',label:'成品'},{key:'packaging',label:'包装盒'},{key:'in_transit',label:'在途'}] as const).map(filter=><button type="button" key={filter.key} className={purchaseFilter===filter.key?'active':''} onClick={()=>setPurchaseFilter(filter.key)}>{filter.label}</button>)}</div>{visiblePurchases.length ? <div className="data-table"><div className="data-head"><span>采购单 / 供应商</span><span>SKU / 类型</span><span>采购数量</span><span>到货数量 / 凭据金额核对</span><span>凭据采购金额</span><span>操作</span></div>{visiblePurchases.map(po=><div className="data-row" key={po.id}><span><strong>{po.number}</strong><small>{po.supplier}</small></span><span><strong>{po.sku}</strong><small>{po.item_type==='finished_goods'?'成品':'包装盒'}</small></span><span>{po.ordered_qty}</span><span><strong>{po.received_qty}/{po.ordered_qty}</strong><small>已到货金额：{po.currency} {po.received_amount}</small><small>未到货金额：{po.currency} {po.remaining_document_amount}</small>{po.receipts.map(receipt=><span className="receipt-history" key={receipt.id}><small>{receipt.received_on} · 到货 {receipt.quantity}</small><button type="button" className="receipt-edit-button" onClick={()=>{setReceiving(null);setEditReceiptError('');setEditingReceipt({purchase:po,receipt})}}>修改数量</button></span>)}</span><span>{po.currency} {po.order_amount}</span><span>{po.received_qty<po.ordered_qty?<button className="secondary-button receive-button" onClick={()=>{setEditingReceipt(null);setReceiving(po);setReceiveSourceKey(crypto.randomUUID())}}>登记到货</button>:"已到齐"}</span></div>)}</div>:<div className="empty-state"><Coffee size={23}/><strong>{purchases.length?'这个筛选下没有采购单':'还没有采购单'}</strong><span>{purchases.length?'选择其他筛选查看采购单。':'新建采购单后登记到货数量，并核对凭据金额。'}</span></div>}{receiving&&<form className="receive-form" onSubmit={receivePurchase}><input type="hidden" name="source_key" value={receiveSourceKey}/><div className="panel-heading"><div><h3>登记到货 · {receiving.number}</h3><p>{receiving.sku} · 剩余可登记 {receiving.ordered_qty-receiving.received_qty} 件</p></div><button type="button" className="secondary-button" onClick={()=>setReceiving(null)}>取消</button></div><div className="form-split"><label>本次到货数量<input name="quantity" type="number" min="1" max={receiving.ordered_qty-receiving.received_qty} defaultValue={receiving.ordered_qty-receiving.received_qty} required/></label><label>收货日期<input name="received_on" type="date" defaultValue={new Date().toLocaleDateString("sv-SE")} required/></label></div>{receiveError&&<div className="form-error">{receiveError}</div>}<button className="primary-button" disabled={busy}>{busy?"保存中…":"保存到货数量"}</button></form>}{editingReceipt&&<form className="receive-form" onSubmit={editPurchaseReceipt}><div className="panel-heading"><div><h3>修改到货数量 · {editingReceipt.purchase.number}</h3><p>{editingReceipt.receipt.received_on} · 原记录 {editingReceipt.receipt.quantity} 件 · {editingReceipt.purchase.sku}</p></div><button type="button" className="secondary-button" onClick={()=>setEditingReceipt(null)}>取消</button></div><label>修改后的到货数量<input name="quantity" type="number" min="1" max={editingReceipt.purchase.ordered_qty-editingReceipt.purchase.received_qty+editingReceipt.receipt.quantity} defaultValue={editingReceipt.receipt.quantity} required/></label><small className="sample-rule-note">直接修订这条收货记录；库存和应付金额会同步调整。已售/已用数量、已付款或已关联发票可能限制修改。</small>{editReceiptError&&<div className="form-error">{editReceiptError}</div>}<button className="primary-button" disabled={busy}>{busy?"保存中…":"保存到货数量"}</button></form>}</div><form className="panel purchase-form" onSubmit={createPurchase}><h2>新建采购单</h2><p>录入凭据金额核对到货进度。必须先归档采购凭证，付款与发票在财务中心处理。</p><label>原始采购凭证<input type="file" accept=".pdf,.csv,.xls,.xlsx,.ofd,.xml,.zip,.txt" required onChange={e=>setPurchaseFile(e.target.files?.[0]||null)}/></label><label>采购单号<input name="number" required placeholder="PO-2026-001"/></label><label>供应商<input name="supplier" required placeholder="供应商名称"/></label><label>商品 SKU<input name="sku" required placeholder="COFFEE-BOX-01"/></label><div className="form-split"><label>类型<select name="item_type"><option value="finished_goods">咖啡成品</option><option value="packaging">包装盒</option></select></label><label>采购数量<input name="quantity" type="number" min="1" required placeholder="0"/></label></div><label>凭据采购总金额（原币）<input name="document_amount" inputMode="decimal" required placeholder="0.00"/></label><details className="purchase-advanced"><summary>会计估值与币种等信息</summary><label>存货单位成本（不含税；用于库存计价）<input name="unit_cost" inputMode="decimal" placeholder="留空时暂按凭据总额÷采购数量估值"/></label><small className="sample-rule-note">采购核对按凭据总金额与到货数量比例计算；存货成本用于库存及销售成本核算，不用于凭据金额核对。</small><label>经营主体编码<input name="entity_code" defaultValue="main" required/></label><label>项目编码（可选）<input name="project_code"/></label><div className="form-split"><label>币种<input name="currency" defaultValue="CNY" required/></label><label>记账汇率<input name="exchange_rate" inputMode="decimal" defaultValue="1" required/></label></div><label>汇率日期<input name="rate_date" type="date" defaultValue={new Date().toLocaleDateString("sv-SE")} required/></label></details>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy?'保存中…':'创建采购单'}</button></form></div>:<InventoryWorkspace inventory={inventory} safetyStocks={safetyStocks} packagingSkus={[...new Set([...purchases.filter(po=>po.item_type==='packaging').map(po=>po.sku),...packagingRules.map(rule=>rule.packaging_sku).filter((sku):sku is string=>Boolean(sku))])]} movements={movements} refresh={refresh}/>}</section>
}

type CoffeeSkuMetric={sku:string;channel:string;sold_quantity:number;returned_quantity:number;net_quantity:number;sales_revenue:string;refunds:string;net_revenue:string;net_cogs:string|null;gross_profit:string|null;unvalued_sales_lines:number}
type CoffeeReport={period:string;currency:string;items:CoffeeSkuMetric[];channels:{channel:string;sold_quantity:number;returned_quantity:number;net_quantity:number;net_revenue:string;net_cogs:string|null;gross_profit:string|null;unvalued_sales_lines:number}[];channel_analysis_available:boolean;channel_analysis_note:string}
function CoffeeMarginAnalysis(){
  const [period,setPeriod]=useState(()=>new Date().toLocaleDateString('sv-SE').slice(0,7));const [report,setReport]=useState<CoffeeReport|null>(null);const [loading,setLoading]=useState(false);const [error,setError]=useState('')
  useEffect(()=>{let live=true;setLoading(true);setError('');fetch(`/api/reports/coffee?period=${period}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'经营分析读取失败');if(live)setReport(data as CoffeeReport)}).catch(reason=>{if(live)setError(reason instanceof Error?reason.message:'本地 API 不可用')}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[period])
  const rows=report?.items||[];const totalRevenue=rows.reduce((sum,row)=>sum+Number(row.net_revenue),0);const totalCogs=rows.some(row=>row.net_cogs===null)?null:rows.reduce((sum,row)=>sum+Number(row.net_cogs),0);const totalProfit=totalCogs===null?null:totalRevenue-totalCogs
  return <section className="coffee-analysis"><div className="panel coffee-analysis-panel"><div className="panel-heading"><div><h2>咖啡单品毛利</h2><p>按销售发生月归集，并扣除当月可追溯的销售退货。</p></div><label>期间<input type="month" value={period} onChange={event=>setPeriod(event.target.value)}/></label></div>{error&&<div className="form-error">{error}</div>}{loading&&!report?<div className="empty-inline">正在汇总销售成本…</div>:!rows.length?<div className="empty-state"><Coffee size={22}/><strong>所选期间暂无已过账销售</strong><span>销售行过账后会按 SKU 显示收入、FIFO 成本和毛利。</span></div>:<><div className="coffee-analysis-summary"><div><span>销售净收入</span><strong>CNY {totalRevenue.toFixed(2)}</strong></div><div><span>销售成本</span><strong>{totalCogs===null?'存在未估值销售':'CNY '+totalCogs.toFixed(2)}</strong></div><div><span>毛利</span><strong>{totalProfit===null?'暂不可完整计算':'CNY '+totalProfit.toFixed(2)}</strong></div></div><div className="data-table"><div className="data-head coffee-margin-head"><span>商品 SKU</span><span>渠道</span><span>净销量</span><span>净收入</span><span>销售成本</span><span>毛利</span><span>毛利率</span></div>{rows.map(row=><div className="data-row coffee-margin-row" key={`${row.sku}:${row.channel}`}><span><strong>{row.sku}</strong><small>销售 {row.sold_quantity} · 退货 {row.returned_quantity}</small></span><span>{row.channel}</span><span>{row.net_quantity}</span><span>CNY {row.net_revenue}<small>退款 {row.refunds}</small></span><span>{row.net_cogs===null?'未估值':`CNY ${row.net_cogs}`}</span><strong>{row.gross_profit===null?'—':`CNY ${row.gross_profit}`}</strong><span>{row.gross_profit===null||Number(row.net_revenue)<=0?'—':`${(Number(row.gross_profit)/Number(row.net_revenue)*100).toFixed(1)}%`}</span></div>)}</div></>}</div><div className="panel coffee-analysis-note"><h3>渠道毛利对比</h3><p>{report?.channel_analysis_note||'正在读取渠道数据。'}</p>{report?.channel_analysis_available&&<div className="channel-margin-list">{report.channels.map(channel=><div className="channel-margin-row" key={channel.channel}><strong>{channel.channel}</strong><span>净收入 CNY {channel.net_revenue}</span><span>成本 {channel.net_cogs===null?'未估值':`CNY ${channel.net_cogs}`}</span><b>{channel.gross_profit===null?'毛利暂不可算':`毛利 CNY ${channel.gross_profit}`}</b></div>)}</div>}<span>库存月均余额快照尚未建立，暂不计算库存周转天数。</span></div></section>
}

function SalesReturnsWorkspace({refresh}:{refresh:()=>Promise<void>}){
  const [lines,setLines]=useState<SalesReturnLine[]>([]);const [selected,setSelected]=useState('');const [quantity,setQuantity]=useState(1);const [sourceKey,setSourceKey]=useState(()=>crypto.randomUUID());const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  async function load(){const response=await fetch('/api/sales/returns');const data=await response.json();if(!response.ok)throw new Error(data.error||'销售行读取失败');setLines(data as SalesReturnLine[])}
  useEffect(()=>{void load().catch(reason=>setError(reason instanceof Error?reason.message:'本地 API 不可用'))},[])
  const line=lines.find(item=>item.id===selected);const remaining=line?line.quantity-line.returned_quantity:0;const remainingPackaging=line?line.quantity*line.packaging_per_unit-line.returned_packaging_quantity:0;const packagingCap=line&&!line.packaging_included?Math.min(remainingPackaging,quantity*line.packaging_per_unit):0
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!line)return;const target=event.currentTarget;const fields=Object.fromEntries(new FormData(target).entries());setBusy(true);setError('');try{const response=await fetch(`/api/sales/lines/${line.id}/return`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,source_key:sourceKey})});const data=await response.json();if(!response.ok)throw new Error(data.error||'销售退货过账失败');await refresh();await load();setSelected('');setQuantity(1);setSourceKey(crypto.randomUUID());target.reset()}catch(reason){setError(reason instanceof Error?reason.message:'销售退货过账失败')}finally{setBusy(false)}}
  return <div className="panel purchase-list"><div className="panel-heading"><div><h2>销售退货</h2><p>按原销售行和 FIFO 批次成本冲回收入、应收、销售成本与库存。</p></div><button className="secondary-button" onClick={()=>void load()}>刷新</button></div><div className="trial-balance-empty">退货收入先抵减未结应收；已收款部分形成应付客户退款。退回包装数量单独登记。旧销售缺少库存层追溯信息时不会自动估价退货。</div><form className="receive-form" onSubmit={submit}><label>原销售行<select value={selected} onChange={event=>{setSelected(event.target.value);setQuantity(1)}} required><option value="">选择原销售行</option>{lines.filter(item=>item.returnable&&item.returned_quantity<item.quantity).map(item=><option key={item.id} value={item.id}>{item.sold_on} · {item.sku} · {item.source_row_key} · 可退 {item.quantity-item.returned_quantity} 件</option>)}</select></label>{line&&<div className="sample-rule-note">来源行 {line.source_row_key} · 已售 {line.quantity} · 已退 {line.returned_quantity} · 单价 CNY {line.unit_price} · 原销售成本 CNY {line.cogs_cny}</div>}<input type="hidden" name="source_key" value={sourceKey}/><small className="sample-rule-note">固定来源键：{sourceKey}</small><div className="form-split"><label>退回成品数量<input name="quantity" type="number" min="1" max={remaining||undefined} value={quantity} onChange={event=>setQuantity(Math.max(1,Number(event.target.value)||1))} required/></label><label>退货日期<input name="returned_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label></div>{line&&!line.packaging_included&&line.packaging_per_unit>0&&<label>同时退回的包装数量（上限 {packagingCap}）<input name="packaging_quantity" type="number" min="0" max={packagingCap} defaultValue="0" required/></label>}{line&&(line.packaging_included||line.packaging_per_unit===0)&&<input type="hidden" name="packaging_quantity" value="0"/>}{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy||!line||!line.returnable||remaining<1}>{busy?'过账中…':'确认销售退货并生成冲回分录'}</button></form><div className="project-actual-table"><div className="project-actual-head"><span>来源销售行</span><span>已售</span><span>已退</span><span>状态</span></div>{lines.map(item=><div className="project-actual-row" key={item.id}><span>{item.sku} · {item.source_row_key}<small>{item.sold_on} · 单价 CNY {item.unit_price}</small></span><span>{item.quantity}</span><span>{item.returned_quantity}</span><strong className={item.returnable?'good':'bad'}>{item.returnable?'可退':'不可追溯'}</strong>{!item.returnable&&item.return_trace_note&&<small>{item.return_trace_note}</small>}</div>)}</div></div>
}

function BikeWorkspace({orders,costs,sales,tab,refresh}:{orders:BikeOrder[];costs:BikeLandedCost[];sales:BikeSale[];tab:Tab;refresh:()=>Promise<void>}){
  const [milestones,setMilestones]=useState([{name:'定金',percentage:'30',due_on:''},{name:'尾款',percentage:'70',due_on:''}]);const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const percentageTotal=milestones.reduce((sum,item)=>sum+(Number(item.percentage)||0),0)
  function changeMilestone(index:number,key:'name'|'percentage'|'due_on',value:string){setMilestones(current=>current.map((item,i)=>i===index?{...item,[key]:value}:item))}
  async function createOrder(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/bike/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,milestones})});const result=await response.json();if(!response.ok)throw new Error(result.error||'ALSVID 采购引用保存失败');form.reset();setMilestones([{name:'定金',percentage:'30',due_on:''},{name:'尾款',percentage:'70',due_on:''}]);await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  async function markDue(id:string){setBusy(true);setError('');try{const response=await fetch('/api/bike/milestones/due',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({milestone_id:id,recognized_on:new Date().toLocaleDateString('sv-SE')})});const data=await response.json();if(!response.ok)throw new Error(data.error||'节点转应付失败');await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  async function receiveOrder(order:BikeOrder,event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const fields=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/bike/receipts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,alsvid_order_no:order.alsvid_order_no})});const data=await response.json();if(!response.ok)throw new Error(data.error||'ALSVID receipt reconciliation failed');form.reset();await refresh()}catch(e){setError(e instanceof Error?e.message:'Local API unavailable')}finally{setBusy(false)}}
  async function saveCost(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/bike/landed-costs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'到岸费用保存失败');form.reset();await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  if(tab==='activity')return <BikeLandedCostWorkspace orders={orders} costs={costs} busy={busy} error={error} saveCost={saveCost}/>;
  if(tab==='actions')return <BikeSalesWorkspace orders={orders} sales={sales} refresh={refresh}/>;
  if(tab==='overview')return <section className="bike-workspace"><div className="bike-columns"><div className="panel bike-order-list"><div className="panel-heading"><div><h2>ALSVID 外部采购引用</h2><p>只收口合同、供应商和付款节点；VIN 与实体库存仍以 ALSVID 为准。</p></div><span className="table-count">{orders.length} 个采购单</span></div>{orders.length?orders.map(order=><article className="bike-order-card" key={order.id}><div className="bike-order-head"><div><strong>{order.alsvid_order_no}</strong><small>{order.supplier} · {order.entity_code} · {order.quantity} 辆 · 下单 {order.ordered_on}</small></div><div className="bike-contract-amount"><strong>{order.currency} {order.contract_amount}</strong><small>参考汇率 {order.exchange_rate} / {order.rate_date}</small></div></div><div className="milestone-list">{order.milestones.map(node=><div className="milestone-row" key={node.id}><span><strong>{node.name} · {node.percentage}%</strong><small>计划 {node.due_on} · {node.currency||order.currency} {node.amount}</small></span><span><i className={`status-pill ${node.status==='paid'?'green':node.status==='due'?'orange':''}`}>{node.status==='planned'?'计划中':node.status==='paid'?'已付':'待付'}</i><small>{node.payable_id?`未付 ${order.currency} ${node.outstanding_amount}`:'尚未转应付'}</small></span>{node.status==='planned'&&order.received_quantity===0&&<button className="secondary-button" disabled={busy||node.due_on>new Date().toLocaleDateString("sv-SE")} onClick={()=>void markDue(node.id)}>{node.due_on>new Date().toLocaleDateString("sv-SE")?"计划未到期":"确认到期并转应付"}</button>}</div>)}</div><form className="bike-receipt-form" onSubmit={event=>void receiveOrder(order,event)}><label>ALSVID receipt row key<input name="source_key" required placeholder="stable receipt id"/></label><label>Received quantity<input name="quantity" type="number" min="1" max={order.quantity-order.received_quantity} defaultValue={order.quantity-order.received_quantity} required/></label><label>Receipt date<input name="received_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><button className="secondary-button" disabled={busy||order.received_quantity>=order.quantity}>{busy?'Saving…':`Reconcile receipt (${order.received_quantity}/${order.quantity})`}</button></form><div className="bike-order-foot">付款后在财务中心按同币种分配银行流水；进项发票可在发票管理中关联对应应付节点。</div></article>):<div className="empty-state"><Bike size={22}/><strong>尚无 ALSVID 采购引用</strong><span>登记外部采购合同和付款里程碑，系统不会重建车辆库存。</span></div>}</div><form className="panel purchase-form bike-order-form" onSubmit={createOrder}><h2>关联 ALSVID 采购单</h2><p>里程碑百分比必须合计 100%；计划节点不会提前计入损益。</p><label>ALSVID 采购单号<input name="alsvid_order_no" required placeholder="ALS-PO-2026-001"/></label><label>代工厂 / 供应商<input name="supplier" required/></label><label>车型 / SKU<input name="sku" required placeholder="ALSVID 商品编码"/></label><label>经营主体编码<input name="entity_code" defaultValue="main" required/></label><div className="form-split"><label>合同币种<select name="currency"><option value="CNY">CNY</option><option value="EUR">EUR</option></select></label><label>合同总额<input name="contract_amount" inputMode="decimal" min="0.01" step="0.01" required/></label></div><label>采购车辆数量（引用 ALSVID 数量）<input name="quantity" type="number" min="1" step="1" required/></label><div className="form-split"><label>合同汇率<input name="exchange_rate" inputMode="decimal" min="0.0001" step="0.0001" defaultValue="1" required/></label><label>汇率日期<input name="rate_date" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label></div><label>合同日期<input name="ordered_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><div className="bike-milestone-editor"><div className="bike-milestone-title"><strong>付款节点</strong><span className={Math.abs(percentageTotal-100)<0.00001?'good':'bad'}>合计 {percentageTotal.toFixed(2)}%</span></div>{milestones.map((node,index)=><div className="bike-milestone-input" key={index}><label>节点名称<input value={node.name} required onChange={e=>changeMilestone(index,'name',e.target.value)}/></label><label>比例 %<input type="number" min="0.01" max="100" step="0.01" value={node.percentage} required onChange={e=>changeMilestone(index,'percentage',e.target.value)}/></label><label>计划日期<input type="date" value={node.due_on} required onChange={e=>changeMilestone(index,'due_on',e.target.value)}/></label><button type="button" className="icon-button" aria-label="删除节点" disabled={milestones.length<=1} onClick={()=>setMilestones(current=>current.filter((_,i)=>i!==index))}><X size={15}/></button></div>)}<button type="button" className="text-link" onClick={()=>setMilestones(current=>[...current,{name:`第 ${current.length+1} 期`,percentage:'0',due_on:''}])}>+ 增加付款节点</button></div>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy||Math.abs(percentageTotal-100)>0.00001}>{busy?'保存中…':'保存采购引用'}</button></form></div></section>
  return <section className="panel bike-placeholder"><div className="empty-state"><Bike size={23}/><strong>自行车销售数据尚未接入</strong><span>此处不会显示虚构销量或利润；销售导入仍需确定来源字段和批次成本对应规则。</span></div></section>
}

function BikeLandedCostWorkspace({orders,costs,busy,error,saveCost}:{orders:BikeOrder[];costs:BikeLandedCost[];busy:boolean;error:string;saveCost:(event:React.FormEvent<HTMLFormElement>)=>void}){
  const names:Record<BikeLandedCost['cost_type'],string>={freight:'海运 / 货代',duty:'关税',warehouse:'海外仓仓配',other:'其他可归属成本',import_vat:'进口增值税（待税务确认）'}
  return <section className="bike-workspace"><div className="bike-landed-layout"><div className="panel bike-order-list"><div className="panel-heading"><div><h2>批次到岸成本</h2><p>合同原币按合同汇率折算；可归属费用按录入汇率折成人民币后除以外部批次数量。</p></div><span className="table-count">{orders.length} 个批次</span></div>{orders.length?orders.map(order=><article className="bike-order-card" key={order.id}><div className="bike-order-head"><div><strong>{order.alsvid_order_no}</strong><small>{order.supplier} · 外部数量 {order.quantity} 辆 · {order.currency} {order.contract_amount}</small></div><div className="bike-contract-amount"><strong>CNY {order.unit_landed_cost_cny} / 辆</strong><small>合同 CNY {order.contract_amount_cny} + 可归属费用 CNY {order.capitalized_landed_cost_cny}</small></div></div><div className="bike-cost-sublist">{costs.filter(cost=>cost.bike_order_id===order.id).map(cost=><span key={cost.id}>{names[cost.cost_type]} · {cost.reference_no||'无引用'} · {cost.currency} {cost.amount}{cost.cost_type==='import_vat'?' · 未计入成本':` · CNY ${cost.base_amount_cny}`}</span>)}</div></article>):<div className="empty-state"><Bike size={22}/><strong>请先关联 ALSVID 采购单</strong><span>每个外部采购引用需要填写整批数量，系统不录入 VIN 或自行车库存。</span></div>}</div><form className="panel purchase-form bike-cost-form" onSubmit={saveCost}><h2>录入物流 / 清关费用</h2><p>费用按单个 ALSVID 采购批次归集，保持来源号和汇率日期可复核。</p><label>费用来源键<input name="source_key" required placeholder="提单号 / 费用单号 / 唯一行号"/></label><label>关联采购批次<select name="bike_order_id" required defaultValue=""><option value="" disabled>选择 ALSVID 采购单</option>{orders.map(order=><option key={order.id} value={order.id}>{order.alsvid_order_no} · {order.supplier} · {order.quantity} 辆</option>)}</select></label><label>费用类别<select name="cost_type" defaultValue="freight"><option value="freight">海运 / 货代费（计入成本）</option><option value="duty">关税（计入成本）</option><option value="warehouse">海外仓仓配（计入成本）</option><option value="other">其他可归属成本</option><option value="import_vat">进口增值税（只留待确认记录）</option></select></label><label>承运方 / 收费方<input name="counterparty" required/></label><label>提单 / 费用参考号<input name="reference_no"/></label><div className="form-split"><label>发生日期<input name="incurred_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><label>原币金额<input name="amount" type="number" min="0.01" step="0.01" required/></label></div><div className="form-split"><label>币种<select name="currency"><option value="CNY">CNY</option><option value="EUR">EUR</option></select></label><label>记账汇率<input name="exchange_rate" type="number" min="0.0001" step="0.0001" defaultValue="1" required/></label></div><label>汇率日期<input name="rate_date" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy||orders.length===0}>{busy?'保存中…':'保存费用记录'}</button></form></div></section>
}

const exhibitionBudgetCategories=['booth_rental','event_fee','sample_cost','decoration','logistics','travel','accommodation','marketing','other'] as const
function ExhibitionWorkspace({projects,expenses,inventory,packagingRules,sampleDispatches,tab,refresh}:{projects:ProjectRow[];expenses:ExpenseRow[];inventory:InventoryRow[];packagingRules:PackagingRule[];sampleDispatches:SampleDispatchRow[];tab:Tab;refresh:()=>Promise<void>}){
  const [selectedCode,setSelectedCode]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  const selected=projects.find(project=>project.code===selectedCode)
  const [profitPeriod,setProfitPeriod]=useState(()=>{const today=new Date();return `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`})
  const [projectReport,setProjectReport]=useState<OperatingReport|null>(null);const [projectReportError,setProjectReportError]=useState('');const [projectReportLoading,setProjectReportLoading]=useState(false)
  useEffect(()=>{if(!selected){setProjectReport(null);return}let cancelled=false;setProjectReportLoading(true);setProjectReportError('');fetch(`/api/reports/operating?${new URLSearchParams({period:profitPeriod,project_code:selected.code})}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'项目损益读取失败');if(!cancelled)setProjectReport(data as OperatingReport)}).catch(e=>{if(!cancelled)setProjectReportError(e instanceof Error?e.message:'本地 API 不可用')}).finally(()=>{if(!cancelled)setProjectReportLoading(false)});return()=>{cancelled=true}},[selected?.code,profitPeriod])
  async function createProject(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'项目创建失败');form.reset();setSelectedCode(result.code);await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  async function saveBudgets(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!selected)return;const form=event.currentTarget;const values=new FormData(form);setBusy(true);setError('');try{const lines=exhibitionBudgetCategories.map(category=>({category,budget_amount:String(values.get(category)||'0')}));const response=await fetch('/api/projects/budgets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_code:selected.code,lines})});const result=await response.json();if(!response.ok)throw new Error(result.error||'预算保存失败');await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  const actualExpenses=selected?expenses.filter(expense=>expense.project_code===selected.code):[]
  const budgetTotal=selected?.budgets.reduce((sum,line)=>sum+Number(line.budget_amount),0)||0
  const actualTotal=selected?.actuals.reduce((sum,line)=>sum+Number(line.actual_amount),0)||0
  const selectedActuals=new Map(selected?.actuals.map(line=>[line.category,Number(line.actual_amount)])||[])
  const selectedSamples=selected?sampleDispatches.filter(item=>item.project_code===selected.code):[]
  if(tab==='overview')return <section className="exhibition-workspace"><div className="project-overview"><div className="panel project-list"><div className="panel-heading"><div><h2>展会项目</h2><p>预算执行与费用实际按项目编码归集；预算余额不代表项目利润。</p></div><span className="table-count">{projects.length} 个项目</span></div>{projects.length?<div className="project-cards">{projects.map(project=><button type="button" key={project.code} className={`project-card ${selectedCode===project.code?'selected':''}`} onClick={()=>setSelectedCode(project.code)}><strong>{project.name}</strong><span>{project.code} · {project.entity_code}</span><small>{project.starts_on} 至 {project.ends_on}</small><small>预算 {project.currency} {project.budgets.reduce((sum,line)=>sum+Number(line.budget_amount),0).toFixed(2)} · 已登记费用 {project.currency} {project.actuals.reduce((sum,line)=>sum+Number(line.actual_amount),0).toFixed(2)}</small></button>)}</div>:<div className="empty-state"><BriefcaseBusiness size={22}/><strong>尚无展会项目</strong><span>创建项目后再录入分类预算与展会费用。</span></div>}</div><form className="panel purchase-form project-form" onSubmit={createProject}><h2>新建项目</h2><p>项目编码是预算、费用和后续收入归集的稳定维度。</p><label>项目编码<input name="code" required placeholder="EVENT-2026-SH"/></label><label>项目名称<input name="name" required placeholder="上海国际展会"/></label><label>经营主体编码<input name="entity_code" defaultValue="main" required/></label><div className="form-split"><label>开始日期<input type="date" name="starts_on" required/></label><label>结束日期<input type="date" name="ends_on" required/></label></div>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy?'保存中…':'创建展会项目'}</button></form></div></section>
  if(tab==='activity')return <section className="exhibition-workspace">{selected?<><div className="panel project-budget-panel"><div className="panel-heading"><div><h2>{selected.name} · 预算与费用</h2><p>{selected.code} · {selected.entity_code} · {selected.starts_on} 至 {selected.ends_on}</p></div><button className="secondary-button" onClick={()=>void refresh()}>刷新</button></div><div className="project-totals"><div><span>预算总额</span><strong>CNY {budgetTotal.toFixed(2)}</strong></div><div><span>已登记项目费用</span><strong>CNY {actualTotal.toFixed(2)}</strong></div><div><span>预算剩余</span><strong>CNY {(budgetTotal-actualTotal).toFixed(2)}</strong></div></div><form className="budget-editor" onSubmit={saveBudgets}><h3>分类预算（CNY）</h3><div className="budget-input-grid">{exhibitionBudgetCategories.map(category=><label key={category}>{expenseCategoryLabels[category]}<input name={category} type="number" min="0" step="0.01" defaultValue={selected.budgets.find(line=>line.category===category)?.budget_amount||'0.00'}/></label>)}</div>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy?'保存中…':'保存分类预算'}</button></form><div className="project-actual-table"><div className="project-actual-head"><span>费用类别</span><span>预算</span><span>已登记实际</span><span>预算余额</span></div>{exhibitionBudgetCategories.map(category=>{const budget=Number(selected.budgets.find(line=>line.category===category)?.budget_amount||0);const actual=selectedActuals.get(category)||0;return <div className="project-actual-row" key={category}><span>{expenseCategoryLabels[category]}</span><span>CNY {budget.toFixed(2)}</span><span>CNY {actual.toFixed(2)}</span><strong>CNY {(budget-actual).toFixed(2)}</strong></div>})}</div><section className="budget-editor project-profit"><div className="panel-heading"><div><h3>项目真实损益</h3><p>按权责发生制分录归集；项目维度用于分析，公司合并报表仍只计同一笔总账分录一次。</p></div><label>期间<input type="month" value={profitPeriod} onChange={event=>setProfitPeriod(event.target.value)}/></label></div>{projectReportLoading?<div className="empty-inline">正在汇总项目损益…</div>:projectReportError?<div className="form-error">{projectReportError}</div>:projectReport?.period===profitPeriod?<><div className="report-lines">{([['项目收入',projectReport.sales_revenue],['销售成本',projectReport.cost_of_goods_sold],['项目毛利',projectReport.gross_profit],['项目经营费用',projectReport.operating_expenses],['项目经营利润',projectReport.operating_profit]] as const).map(([label,value],index)=><div className={`report-line ${index===2||index===4?'report-total':''}`} key={label}><span>{label}</span><strong>CNY {Number(value).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div>)}{Object.entries(projectReport.operating_expenses_by_category).map(([category,value])=><div className="report-line report-category" key={category}><span>　{expenseCategoryLabels[category]||category}</span><strong>CNY {Number(value).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div>)}</div><p className="report-caveat">此结果仅含本地已过账数据，费用完整性尚未核对。预算执行为项目全周期累计，损益按所选月份汇总；未分配给该项目的公司费用不会自动分摊。</p></>:<div className="empty-inline">所选期间的项目损益暂不可用。</div>}</section><div className="project-expense-entry"><ExpenseForm refresh={refresh} defaultBusinessLine="exhibition" defaultEntityCode={selected.entity_code} defaultProjectCode={selected.code} lockDimensions/></div><div className="project-expense-list"><h3>项目费用明细</h3>{actualExpenses.length?actualExpenses.map(item=><div key={item.id}><span>{item.incurred_on} · {expenseCategoryLabels[item.category]||item.category} · {item.counterparty}</span><strong>CNY {item.amount}</strong></div>):<div className="empty-inline">项目尚无已登记经营费用。</div>}<h3>样品耗用与归还</h3>{selectedSamples.length?selectedSamples.map(item=><div key={item.id}><span>{item.dispatched_on} · {item.sku} · 发出 {item.quantity} / 归还 {item.returned_quantity}</span><strong>净样品费用 CNY {item.outstanding_cost}</strong></div>):<div className="empty-inline">尚无样品调度记录。</div>}</div><p className="report-caveat">预算是执行控制口径，不能用预算余额替代项目损益。</p></div></>:<div className="panel project-budget-panel"><div className="empty-state"><BriefcaseBusiness size={22}/><strong>先选择或创建一个展会项目</strong><span>项目预算和费用都必须归属到具体项目。</span></div></div>}</section>
  return <section className="exhibition-workspace"><div className="panel project-budget-panel sample-workspace"><div className="panel-heading"><div><h2>样品调度与归还</h2><p>按 FIFO 发出商品及规则包装，成本计入展会项目样品费用；归还按原批次成本冲回。</p></div><span className="table-count">{sampleDispatches.length} 笔发出</span></div>{!selected&&<label className="sample-project-select">选择展会项目<select value={selectedCode} onChange={e=>setSelectedCode(e.target.value)}><option value="">请选择项目</option>{projects.map(project=><option key={project.code} value={project.code}>{project.code} · {project.name}</option>)}</select></label>}{selected?<SampleDispatchForm project={selected} inventory={inventory} rules={packagingRules} refresh={refresh}/>:<div className="empty-inline">创建并选择项目后，才可以登记样品出库。</div>}<div className="sample-dispatch-list">{sampleDispatches.filter(item=>!selectedCode||item.project_code===selectedCode).map(item=><article className="sample-dispatch-card" key={item.id}><div><strong>{item.project_name} · {item.sku}</strong><small>{item.dispatched_on} · {item.source_key} · 发出 {item.quantity}，归还 {item.returned_quantity}，在外 {item.outstanding_quantity}</small></div><div className="sample-cost"><span>发出成本 CNY {item.total_cost}</span><small>当前计入项目费用 CNY {item.outstanding_cost}</small></div>{item.outstanding_quantity>0&&<SampleReturnForm dispatch={item} refresh={refresh}/>}</article>)}</div><p className="report-caveat">归还只冲回完好且实际返回的样品及对应包装；损坏或消耗部分继续留在项目样品费用中。库存仍仅允许人民币批次参与样品调度。</p></div></section>
}

function SampleDispatchForm({project,inventory,rules,refresh}:{project:ProjectRow;inventory:InventoryRow[];rules:PackagingRule[];refresh:()=>Promise<void>}){
  const [sku,setSku]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const eligible=inventory.filter(item=>{if(item.currency!=='CNY'||item.quantity<=0)return false;const rule=rules.find(row=>row.sku===item.sku);if(!rule)return false;if(rule.packaging_per_unit>0&&!rule.packaging_included){const box=inventory.find(row=>row.sku===rule.packaging_sku&&row.currency==='CNY');if(!box||box.quantity<rule.packaging_per_unit)return false}return true})
  const selectedSku=eligible.find(item=>item.sku===sku)?.sku||eligible[0]?.sku||''
  const selectedItem=eligible.find(item=>item.sku===selectedSku);const rule=rules.find(row=>row.sku===selectedSku)
  const packageInventory=rule&&rule.packaging_per_unit>0&&!rule.packaging_included?inventory.find(item=>item.sku===rule.packaging_sku&&item.currency==='CNY'):null
  const maxQuantity=selectedItem&&rule?Math.min(selectedItem.quantity,rule.packaging_per_unit>0&&!rule.packaging_included?Math.floor((packageInventory?.quantity||0)/rule.packaging_per_unit):Number.MAX_SAFE_INTEGER):0
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/projects/samples/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,project_code:project.code,sku:selectedSku,quantity:Number(data.quantity)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'样品出库失败');form.reset();await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  return <form className="sample-dispatch-form" onSubmit={submit}><h3>登记样品发出 · {project.name}</h3><div className="form-split"><label>成品 SKU<select value={selectedSku} onChange={e=>setSku(e.target.value)} required disabled={!eligible.length}>{eligible.map(item=><option key={item.sku} value={item.sku}>{item.sku} · 可用 {item.quantity} · CNY {item.value}</option>)}</select></label><label>发出数量<input name="quantity" type="number" min="1" max={maxQuantity} required disabled={!eligible.length} placeholder="0"/></label></div><div className="form-split"><label>发出日期<input name="dispatched_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><label>调度单号 / 来源键<input name="source_key" required placeholder="SAMPLE-EVENT-001"/></label></div>{selectedItem&&rule&&<small className="sample-rule-note">库存成本按 FIFO 结转；{rule.packaging_included?'工厂已含包装':rule.packaging_per_unit?`另扣 ${rule.packaging_sku} × ${rule.packaging_per_unit}/件`:'无额外包装耗用'}。最高可发 {maxQuantity} 件。</small>}{!eligible.length&&<div className="empty-inline">没有满足人民币库存、包装规则和包装库存条件的商品 SKU。</div>}{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy||!eligible.length||maxQuantity<1}>{busy?'处理中…':'确认发出并计入样品费用'}</button></form>
}

function SampleReturnForm({dispatch,refresh}:{dispatch:SampleDispatchRow;refresh:()=>Promise<void>}){const [busy,setBusy]=useState(false);const [error,setError]=useState('');async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/projects/samples/return',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,dispatch_id:dispatch.id,quantity:Number(data.quantity)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'样品归还登记失败');form.reset();await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}return <form className="sample-return-form" onSubmit={submit}><label>归还数量<input name="quantity" type="number" min="1" max={dispatch.outstanding_quantity} required placeholder={`最多 ${dispatch.outstanding_quantity}`}/></label><label>归还日期<input name="returned_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><label>归还单号 / 来源键<input name="source_key" required placeholder="RETURN-EVENT-001"/></label><button className="secondary-button" disabled={busy}>{busy?'处理中…':'登记归还'}</button>{error&&<small className="form-error">{error}</small>}</form>}

function InventoryAdjustmentForm({refresh}:{refresh:()=>Promise<void>}){const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [direction,setDirection]=useState<'gain'|'loss'>('loss');async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const raw=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/inventory/adjustments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...raw,direction,quantity:Number(raw.quantity)})});const result=await response.json();if(!response.ok)throw new Error(result.error||'盘点调整失败');form.reset();await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}return <form className="panel purchase-form inventory-adjustment-form" onSubmit={event=>void submit(event)}><h2>盘点差异调整</h2><p>盘盈按核实成本新增独立批次；盘亏按所选币种 FIFO 扣减。调整生成盘点损益凭证。</p><div className="form-split"><label>方向<select value={direction} onChange={event=>setDirection(event.target.value as 'gain'|'loss')}><option value="loss">盘亏</option><option value="gain">盘盈</option></select></label><label>库存类型<select name="item_type" defaultValue="finished_goods"><option value="finished_goods">咖啡成品</option><option value="packaging">包装盒</option></select></label></div><label>SKU<input name="sku" required placeholder="选择已登记商品或包装 SKU"/></label><div className="form-split"><label>数量<input name="quantity" type="number" min="1" step="1" required/></label><label>币种<input name="currency" defaultValue="CNY" maxLength={3} required/></label></div><div className="form-split"><label>单位成本（盘盈必填）<input name="unit_cost" type="number" min="0" step="0.0001" defaultValue="0" required/></label><label>记账汇率<input name="exchange_rate" type="number" min="0.00000001" step="0.00000001" defaultValue="1" required/></label></div><div className="form-split"><label>盘点日期<input name="adjusted_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><label>主体编码<input name="entity_code" defaultValue="main" required/></label></div><label>原因 / 盘点凭据<input name="reason" required maxLength={500} placeholder="盘点单号及差异原因"/></label><label>来源凭证键<input name="source_key" required maxLength={160} placeholder="盘点单号:行号"/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy?'过账中…':'确认盘点调整'}</button></form>}

function InventoryWorkspace({inventory,safetyStocks,packagingSkus,movements,refresh}:{inventory:InventoryRow[];safetyStocks:SafetyStockRow[];packagingSkus:string[];movements:InventoryMovement[];refresh:()=>Promise<void>}) {
  const [safetySku,setSafetySku]=useState('');const [safetyQuantity,setSafetyQuantity]=useState('');const [safetyError,setSafetyError]=useState('');const [safetyBusy,setSafetyBusy]=useState(false)
  async function saveSafetyStock(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setSafetyBusy(true);setSafetyError('');try{const response=await fetch('/api/inventory/safety-stock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sku:safetySku,safety_quantity:Number(safetyQuantity)})});const data=await response.json();if(!response.ok)throw new Error(data.error||'安全库存保存失败');setSafetySku('');setSafetyQuantity('');await refresh()}catch(error){setSafetyError(error instanceof Error?error.message:'本地 API 不可用')}finally{setSafetyBusy(false)}}
  const kind=(type:string)=>type==='receipt'?'收货入库':type==='sale'?'销售出库':type==='sale_return'?'销售退货入库':type==='sample_dispatch'?'展会样品发出':type==='sample_return'?'展会样品归还':type
  return <div className="inventory-workspace"><InventoryAdjustmentForm refresh={refresh}/><div className="panel stock-list"><div className="panel-heading"><div><h2>实时库存余额</h2><p>按 SKU 与原币分组，存货成本为剩余 FIFO 批次成本。</p></div><button className="secondary-button" onClick={()=>void refresh()}>刷新</button></div>{inventory.length?<div className="data-table"><div className="data-head inventory-head"><span>SKU / 币种</span><span>可用数量</span><span>存货成本</span></div>{inventory.map(row=><div className="data-row inventory-row" key={`${row.sku}:${row.currency}`}><span><strong>{row.sku}</strong><small>{row.currency}</small></span><span>{row.quantity}</span><span>{row.currency} {row.value}</span></div>)}</div>:<div className="empty-state"><PackageIcon size={23}/><strong>暂无可用库存</strong><span>采购收货并确认后，库存会出现在此处。</span></div>}</div><div className="panel safety-stock-panel"><div className="panel-heading"><div><h2>包装盒安全库存</h2><p>库存低于设定数量时显示预警；阈值只用于提醒，不会自动采购。</p></div></div><form className="safety-stock-form" onSubmit={saveSafetyStock}><label>包装盒 SKU<input value={safetySku} onChange={event=>setSafetySku(event.target.value)} required placeholder="BOX-01" list="inventory-skus"/></label><datalist id="inventory-skus">{[...new Set([...packagingSkus,...safetyStocks.map(row=>row.sku)])].map(sku=><option key={sku} value={sku}/>)}</datalist><label>预警数量<input type="number" min="0" step="1" value={safetyQuantity} onChange={event=>setSafetyQuantity(event.target.value)} required placeholder="0"/></label><button className="secondary-button" disabled={safetyBusy}>{safetyBusy?'保存中…':'保存预警线'}</button></form>{safetyError&&<div className="form-error">{safetyError}</div>}<div className="safety-stock-list">{safetyStocks.map(item=>{const stock=inventory.filter(row=>row.sku===item.sku).reduce((sum,row)=>sum+row.quantity,0);const low=stock<item.safety_quantity;return <div className="safety-stock-row" key={item.sku}><strong>{item.sku}</strong><span>库存 {stock} / 预警线 {item.safety_quantity}</span><b className={low?'bad':'good'}>{low?'库存偏低':'正常'}</b></div>})}{!safetyStocks.length&&<div className="empty-inline">尚未设置安全库存预警线。</div>}</div></div><div className="panel movement-list"><div className="panel-heading"><div><h2>库存出入库明细</h2><p>最近 500 条记录；历史未保存币种的行会标记为“未标注”。</p></div><span className="table-count">{movements.length} 条</span></div>{movements.length?<div className="movement-table"><div className="movement-head"><span>日期 / SKU</span><span>类型 / 来源</span><span>数量</span><span>单位成本</span></div>{movements.map(row=><div className="movement-row" key={row.id}><span><strong>{row.created_at.slice(0,10)}</strong><small>{row.sku}</small></span><span><strong>{kind(row.movement_type)}</strong><small>{row.source_type} · {row.source_id.slice(0,8)}</small></span><span className={row.quantity<0?'movement-out':'movement-in'}>{row.quantity>0?'+':''}{row.quantity}</span><span>{row.currency==='UNKNOWN'?'币种未标注':row.currency} {row.unit_cost}</span></div>)}</div>:<div className="empty-state"><PackageIcon size={22}/><strong>暂无库存流水</strong><span>收货入库或销售出库后，流水会在这里按来源留存。</span></div>}</div></div>
}

function BankAccountCoverage({period,send}:{period:string;send:(path:string,payload:unknown)=>Promise<unknown>}){const [data,setData]=useState<BankAccountsResponse|null>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(false);async function load(){setLoading(true);try{const response=await fetch('/api/bank/accounts?period='+period);const value=await response.json();if(!response.ok)throw new Error(value.error||'银行账户清单读取失败');setData(value as BankAccountsResponse);setError('')}catch(reason){setError(reason instanceof Error?reason.message:'本地 API 不可用')}finally{setLoading(false)}}useEffect(()=>{void load()},[period]);async function submitForm(event:React.FormEvent<HTMLFormElement>,path:string){event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget).entries());const result=await send(path,values);if(result)await load()}return <div className="panel bank-coverage-panel"><div className="panel-heading"><div><h2>账户覆盖与银行对账 · {period}</h2><p>按真实银行对账单录入账户期初、期末余额；已导入流水应与账单收支核平。</p></div><button className="secondary-button" onClick={()=>void load()}>{loading?'刷新中…':'刷新'}</button></div>{data&&<div className="bank-coverage-status"><strong className={data.bank_coverage_complete?'good':'bad'}>{data.bank_coverage_complete?'账户清单已确认且逐户核平':'尚未确认账户完整性或仍有账户未核平'}</strong><span>已登记账户 {data.active_account_count} 个 · 本期清单确认：{data.account_inventory_confirmed?'是':'否'}</span>{data.coverage_note&&<small>确认说明：{data.coverage_note}</small>}</div>}{error&&<div className="form-error">{error}</div>}<div className="bank-account-list">{data?.accounts.map(account=><article className="bank-account-card" key={account.id}><div className="bank-account-summary"><strong>{account.account_name} · {account.currency}</strong><span>{account.transactions} 笔 · 流入 {account.inflow} · 流出 {account.outflow}</span><strong className={account.reconciled?'good':'bad'}>{account.difference===null?'缺少对账单':account.reconciled?'已核平':`差额 ${account.currency} ${account.difference}`}</strong></div><form className="bank-reconciliation-form" onSubmit={event=>void submitForm(event,'/api/bank/reconciliation')}><input type="hidden" name="bank_account_id" value={account.id}/><input type="hidden" name="period" value={period}/><label>期初余额<input name="opening_balance" type="number" step="0.01" defaultValue={account.opening_balance||''} required/></label><label>期末余额<input name="closing_balance" type="number" step="0.01" defaultValue={account.closing_balance||''} required/></label><label>银行对账单编号/来源<input name="statement_reference" defaultValue={account.statement_reference||''} required/></label><label>说明<input name="note" defaultValue={account.note||''} placeholder="差异说明或复核凭据"/></label><button className="secondary-button">保存并核对</button></form></article>)}</div><div className="bank-account-setup"><form onSubmit={event=>void submitForm(event,'/api/bank/accounts')}><strong>登记企业银行账户</strong><input name="account_name" required placeholder="账户名称或末四位标识"/><select name="currency" defaultValue="CNY"><option value="CNY">CNY</option><option value="EUR">EUR</option><option value="USD">USD</option></select><button className="secondary-button">添加账户</button></form><form onSubmit={event=>void submitForm(event,'/api/bank/accounts/coverage')}><input type="hidden" name="period" value={period}/><label>账户清单核实说明<input name="note" required placeholder="例如：已对照网银企业账户列表逐户核实"/></label><button className="primary-button" disabled={!data?.accounts.length}>确认已登记全部企业银行账户</button></form></div></div>}

function BankFxReview({bank,send,onComplete}:{bank:BankRow;send:(path:string,payload:unknown)=>Promise<unknown>;onComplete:()=>void}){async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());const result=await send('/api/bank/fx-review',{...data,bank_transaction_id:bank.id});if(result)onComplete()}return <form className="fx-review-form" onSubmit={event=>void submit(event)}><strong>补录外币流水的人民币账面值</strong><div className="form-split"><label>交易日汇率<input name="exchange_rate" type="number" min="0.00000001" step="0.00000001" required/></label><label>汇率日期<input name="rate_date" type="date" defaultValue={bank.transaction_on} required/></label></div><label>汇率来源 / 凭据<input name="rate_source" required placeholder="银行牌价 / 记账凭证 / 人工复核依据"/></label><button className="secondary-button">保存汇率估值</button></form>}
function BankCashFlowControl({bank,send}:{bank:BankRow;send:(path:string,payload:unknown)=>Promise<unknown>}){const [category,setCategory]=useState(bank.cash_flow_category||'unclassified');const [note,setNote]=useState(bank.cash_flow_note||'');const [busy,setBusy]=useState(false);async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const result=await send('/api/bank/cash-flow-classification',{bank_transaction_id:bank.id,category,note});if(result&&category==='unclassified')setNote('');setBusy(false)}return <form className="bank-cash-flow-control" onSubmit={event=>void submit(event)}><select aria-label="现金流分类" value={category} onChange={event=>setCategory(event.target.value as BankRow['cash_flow_category'])}><option value="unclassified">现金流待分类</option><option value="operating">经营活动</option><option value="investing">投资活动</option><option value="financing">筹资活动</option><option value="transfer">内部转账</option></select><input aria-label="现金流分类说明" value={note} onChange={event=>setNote(event.target.value)} placeholder={['investing','financing','transfer'].includes(category)?'分类说明（必填）':'分类说明（可选）'} required={['investing','financing','transfer'].includes(category)}/><button className="secondary-button" disabled={busy||category===bank.cash_flow_category&&(note||'')===(bank.cash_flow_note||'')}>{busy?'保存中…':'保存分类'}</button></form>}
function OpenItemFxReview({item,send,refresh}:{item:OpenItem;send:(path:string,payload:unknown)=>Promise<unknown>;refresh:()=>Promise<void>}){async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());const result=await send('/api/open-items/fx-review',{...data,open_item_id:item.id});if(result){form.reset()}}return <form className="fx-review-form" onSubmit={event=>void submit(event)}><strong>旧外币余额缺少账面汇率</strong><div className="form-split"><label>原始记账汇率<input name="exchange_rate" type="number" min="0.00000001" step="0.00000001" required/></label><label>汇率日期<input name="rate_date" type="date" required/></label></div><label>汇率来源 / 凭据<input name="rate_source" required placeholder="原记账凭证 / 历史汇率依据"/></label><button className="secondary-button">登记账面汇率</button></form>}

type PlatformImportField='period'|'platform'|'store_name'|'gross_amount'|'refund_amount'|'subsidy_amount'|'platform_fee_amount'|'settlement_amount'|'bank_received_amount'|'declared_sales_amount'|'evidence_ref'|'note'
const platformImportFields:PlatformImportField[]=['period','platform','store_name','gross_amount','refund_amount','subsidy_amount','platform_fee_amount','settlement_amount','bank_received_amount','declared_sales_amount','evidence_ref','note']
const platformImportLabels:Record<PlatformImportField,string>={period:'账期（可选）',platform:'平台名称',store_name:'店铺 / 商户',gross_amount:'订单交易总额',refund_amount:'退款金额',subsidy_amount:'平台补贴',platform_fee_amount:'平台佣金 / 服务费',settlement_amount:'平台结算金额',bank_received_amount:'银行实际到账（可选）',declared_sales_amount:'申报销售额（可选）',evidence_ref:'账单编号 / 凭据引用（可选）',note:'差异说明（可选）'}
const platformImportAliases:Record<PlatformImportField,string[]>={period:['period','账期','月份','统计月份','month'],platform:['platform','平台','平台名称','渠道'],store_name:['store_name','店铺','店铺名称','商户','商户名称','店铺/商户'],gross_amount:['gross_amount','订单交易总额','平台交易金额','交易总额','客户支付金额','订单支付金额','收入总额'],refund_amount:['refund_amount','退款金额','退款'],subsidy_amount:['subsidy_amount','平台补贴','补贴金额'],platform_fee_amount:['platform_fee_amount','平台佣金','平台服务费','佣金及服务费','平台费用','手续费'],settlement_amount:['settlement_amount','平台结算金额','结算金额','结算到账'],bank_received_amount:['bank_received_amount','银行实际到账','银行到账金额','银行到账'],declared_sales_amount:['declared_sales_amount','申报销售额','税务申报销售额','申报金额'],evidence_ref:['evidence_ref','账单编号','凭据编号','来源凭据','报表编号'],note:['note','说明','备注','差异说明']}
function PlatformIncomeImport({period,onSaved}:{period:string;onSaved:()=>Promise<void>}){
  const [fileName,setFileName]=useState('');const [headers,setHeaders]=useState<string[]>([]);const [rows,setRows]=useState<CsvRow[]>([]);const [map,setMap]=useState<Partial<Record<PlatformImportField,string>>>({});const [operator,setOperator]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [results,setResults]=useState<Record<number,string>>({})
  async function choose(file?:File){if(!file)return;setFileName(file.name);setError('');setResults({});setHeaders([]);setRows([]);if(!/\.csv$/i.test(file.name)){setError('当前只支持 CSV。请先将平台月度汇总另存为 UTF-8 CSV；文件只在本机读取。');return}try{const parsed=parseCsv(await file.text());if(parsed.length<2)throw new Error('CSV 必须包含表头和至少一条月度汇总。');const cols=parsed[0].map((value,index)=>value.trim().replace(/^\uFEFF/,'')||`列${index+1}`);const data=parsed.slice(1).map(cells=>Object.fromEntries(cols.map((header,index)=>[header,(cells[index]??'').trim()])));const find=(field:PlatformImportField)=>cols.find(header=>platformImportAliases[field].some(alias=>alias.toLowerCase()===header.trim().toLowerCase()))||'';setHeaders(cols);setRows(data);setMap(Object.fromEntries(platformImportFields.map(field=>[field,find(field)])) as Partial<Record<PlatformImportField,string>>)}catch(reason){setError(reason instanceof Error?reason.message:'无法读取 CSV')}}
  const prepared=useMemo(()=>{const counts=new Map<string,number>();for(const row of rows){const sourcePeriod=map.period?row[map.period]?.trim()||period:period;const platform=map.platform?row[map.platform]?.trim()||'':'';const store=map.store_name?row[map.store_name]?.trim()||'':'';if(platform&&store){const key=`${sourcePeriod}\u0000${platform}\u0000${store}`;counts.set(key,(counts.get(key)||0)+1)}}return rows.map((row,index)=>{const get=(field:PlatformImportField)=>{const column=map[field];return column?row[column]?.trim()||'':''};const sourcePeriod=get('period')||period;const platform=get('platform');const store=get('store_name');const requiredAmounts=['gross_amount','refund_amount','subsidy_amount','platform_fee_amount','settlement_amount'] as const;const optionalAmounts=['bank_received_amount','declared_sales_amount'] as const;const parsedAmounts:Record<string,string|null>={};const errors:string[]=[];if(sourcePeriod!==period)errors.push(`账期 ${sourcePeriod} 与当前 ${period} 不一致`);if(!platform)errors.push('平台名称缺失');if(!store)errors.push('店铺 / 商户缺失');for(const field of requiredAmounts){if(!map[field]||!get(field)){errors.push(`${platformImportLabels[field]}缺失`);continue}const value=Number(get(field).replace(/[,$€£¥￥\s]/g,''));if(!Number.isFinite(value)||value<0)errors.push(`${platformImportLabels[field]}不是有效的非负金额`);else parsedAmounts[field]=value.toFixed(2)}for(const field of optionalAmounts){const raw=get(field);if(!raw){parsedAmounts[field]=null;continue}const value=Number(raw.replace(/[,$€£¥￥\s]/g,''));if(!Number.isFinite(value)||value<0)errors.push(`${platformImportLabels[field]}不是有效的非负金额`);else parsedAmounts[field]=value.toFixed(2)}if(!operator.trim())errors.push('请填写本次导入的录入人');const key=`${sourcePeriod}\u0000${platform}\u0000${store}`;if(platform&&store&&(counts.get(key)||0)>1)errors.push('同一文件中平台、店铺和账期重复；该组行均未导入');const evidence=get('evidence_ref')||`${fileName} · CSV 第 ${index+2} 行`;const payload:Record<string,string|null>={period:sourcePeriod,platform,store_name:store,...parsedAmounts,evidence_ref:evidence,note:get('note')||'',changed_by:operator.trim(),action_key:crypto.randomUUID()};return {index,payload,errors}})},[rows,map,period,operator,fileName])
  const valid=prepared.filter(item=>item.errors.length===0)
  async function submit(){setBusy(true);setError('');const next={...results};try{for(const item of valid){try{const response=await fetch('/api/platform-income/reconciliation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item.payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'保存失败');next[item.index]=result.duplicate?'已记录（重复请求）':'已保存'}catch(reason){next[item.index]=reason instanceof Error?reason.message:'本地 API 不可用'}}setResults(next);await onSaved()}catch(reason){setError(reason instanceof Error?reason.message:'刷新对账失败')}finally{setBusy(false)}}
  return <div className="panel finance-panel platform-import-panel"><div className="panel-heading"><div><h3>导入平台月度汇总 CSV</h3><p>每行对应一个平台、店铺和账期的汇总；不是逐笔订单明细。列映射与预览在本机完成，不上传原文件；已有记录重复导入会留修订历史。</p></div><span className="local-only">本地处理</span></div><label className="file-drop platform-file-drop"><FileSpreadsheet size={20}/><strong>{fileName||'选择平台月度汇总 CSV'}</strong><span>支持平台订单 / 退款 / 结算汇总表，UTF-8 CSV</span><input type="file" accept=".csv,text/csv" onChange={event=>void choose(event.target.files?.[0])}/></label>{headers.length>0&&<><div className="mapping-grid platform-mapping-grid">{platformImportFields.map(field=><label key={field}>{platformImportLabels[field]}<select value={map[field]||''} onChange={event=>setMap({...map,[field]:event.target.value})}><option value="">{['period','bank_received_amount','declared_sales_amount','evidence_ref','note'].includes(field)?'未映射（按说明处理）':'请选择列'}</option>{headers.map(header=><option key={header} value={header}>{header}</option>)}</select></label>)}</div><div className="platform-import-footer"><label>录入人<input value={operator} onChange={event=>setOperator(event.target.value)} placeholder="本次导入的操作人" required/></label><div className="preview-summary"><span>共 {rows.length} 行</span><span className="good">可导入 {valid.length}</span><span className={rows.length-valid.length?'bad':''}>需复核 {rows.length-valid.length}</span><button type="button" className="primary-button" disabled={busy||!valid.length} onClick={()=>void submit()}>{busy?'逐行保存…':'确认导入有效行'}</button></div></div><div className="import-table-wrap"><table className="import-table"><thead><tr><th>行</th><th>账期</th><th>平台 / 店铺</th><th>交易总额</th><th>退款</th><th>平台费用</th><th>结算</th><th>校验</th></tr></thead><tbody>{prepared.slice(0,100).map(item=><tr key={item.index}><td>{item.index+2}</td><td>{item.payload.period}</td><td>{item.payload.platform||'—'} / {item.payload.store_name||'—'}</td><td>{item.payload.gross_amount||'—'}</td><td>{item.payload.refund_amount||'—'}</td><td>{item.payload.platform_fee_amount||'—'}</td><td>{item.payload.settlement_amount||'—'}</td><td><span className={`row-result ${results[item.index]?'posted':item.errors.length?'rejected':'ready'}`}>{results[item.index]||item.errors.join('；')||'可导入'}</span></td></tr>)}</tbody></table>{rows.length>100&&<div className="empty-inline">预览前 100 行；共 {rows.length} 行。</div>}</div></>}{error&&<div className="form-error">{error}</div>}</div>
}

function PlatformIncomeWorkspace({period}:{period:string}){
  const emptyForm={platform:'',store_name:'',gross_amount:'0.00',refund_amount:'0.00',subsidy_amount:'0.00',platform_fee_amount:'0.00',settlement_amount:'0.00',bank_received_amount:'',declared_sales_amount:'',evidence_ref:'',note:'',changed_by:''}
  const [data,setData]=useState<PlatformIncomeStatus|null>(null);const [form,setForm]=useState(emptyForm);const [editing,setEditing]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  async function load(){const response=await fetch(`/api/platform-income/reconciliation?period=${period}`);const result=await response.json();if(!response.ok)throw new Error(result.error||'平台收入对账读取失败');setData(result as PlatformIncomeStatus)}
  useEffect(()=>{setData(null);setError('');void load().catch(reason=>setError(reason instanceof Error?reason.message:'本地 API 不可用'))},[period])
  async function save(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');try{const response=await fetch('/api/platform-income/reconciliation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form,period,action_key:crypto.randomUUID()})});const result=await response.json();if(!response.ok)throw new Error(result.error||'平台收入记录保存失败');setForm(emptyForm);setEditing(false);await load()}catch(reason){setError(reason instanceof Error?reason.message:'本地 API 不可用')}finally{setBusy(false)}}
  function edit(row:PlatformIncomeRecord){setEditing(true);setForm({platform:row.platform,store_name:row.store_name,gross_amount:row.gross_amount,refund_amount:row.refund_amount,subsidy_amount:row.subsidy_amount,platform_fee_amount:row.platform_fee_amount,settlement_amount:row.settlement_amount,bank_received_amount:row.bank_received_amount||'',declared_sales_amount:row.declared_sales_amount||'',evidence_ref:row.evidence_ref,note:row.note,changed_by:row.updated_by})}
  const totals=data?.totals
  return <div className="platform-income-workspace"><PlatformIncomeImport period={period} onSaved={load}/><div className="panel finance-panel"><div className="panel-heading"><div><h2>平台收入与申报核对 · {period}</h2><p>订单金额取自平台订单/交易报表；退款、补贴、结算和银行到账分别核对。</p></div><button className="secondary-button" onClick={()=>void load()}>刷新</button></div><div className="trial-balance-summary"><span>平台交易总额 CNY {totals?.gross_amount||'0.00'}</span><span>退款 CNY {totals?.refund_amount||'0.00'}</span><span>补贴 CNY {totals?.subsidy_amount||'0.00'}</span><span>平台净额 CNY {totals?.platform_net_amount||'0.00'}</span><span>平台结算 CNY {totals?.settlement_amount||'0.00'}</span><span>银行到账 CNY {data?.bank_received_count?totals?.bank_received_amount:'未录入'}</span></div><div className="trial-balance-empty">平台净额 = 交易总额 + 补贴 − 退款；预期结算 = 平台净额 − 平台费用。系统账内销售收入 CNY {data?.accounting_sales_revenue_cny||'0.00'}，税务申报销售额 CNY {data?.declared_sales_count?totals?.declared_sales_amount:'未录入'}。这些口径可能因含税/不含税及确认期间不同而有差异，本页用于对照，不自动生成税务结论。</div>{error&&<div className="form-error">{error}</div>}</div>
  <div className="platform-income-grid"><form className="panel finance-panel platform-income-form" onSubmit={save}><div className="panel-heading"><div><h3>{editing?'修订平台对账':'登记平台月度汇总'}</h3><p>每个平台与店铺每月一条；交易额取订单报表，不用结算或提现金额代替。</p></div>{editing&&<button type="button" className="secondary-button" onClick={()=>{setEditing(false);setForm(emptyForm)}}>取消</button>}</div><label>平台名称<input value={form.platform} onChange={e=>setForm({...form,platform:e.target.value})} placeholder="淘宝 / 京东 / 微信支付" required/></label><label>店铺 / 商户<input value={form.store_name} onChange={e=>setForm({...form,store_name:e.target.value})} placeholder="店铺名或商户号" required/></label><div className="form-split"><label>订单交易金额（客户支付，CNY）<input type="number" min="0" step="0.01" value={form.gross_amount} onChange={e=>setForm({...form,gross_amount:e.target.value})} required/></label><label>退款金额（CNY）<input type="number" min="0" step="0.01" value={form.refund_amount} onChange={e=>setForm({...form,refund_amount:e.target.value})} required/></label></div><div className="form-split"><label>平台补贴（CNY）<input type="number" min="0" step="0.01" value={form.subsidy_amount} onChange={e=>setForm({...form,subsidy_amount:e.target.value})} required/></label><label>平台佣金 / 服务费（CNY）<input type="number" min="0" step="0.01" value={form.platform_fee_amount} onChange={e=>setForm({...form,platform_fee_amount:e.target.value})} required/></label></div><div className="form-split"><label>平台结算金额（CNY）<input type="number" min="0" step="0.01" value={form.settlement_amount} onChange={e=>setForm({...form,settlement_amount:e.target.value})} required/></label><label>银行实际到账（可选）<input type="number" min="0" step="0.01" value={form.bank_received_amount} onChange={e=>setForm({...form,bank_received_amount:e.target.value})}/></label></div><label>税务申报销售额（可选，CNY）<input type="number" min="0" step="0.01" value={form.declared_sales_amount} onChange={e=>setForm({...form,declared_sales_amount:e.target.value})}/></label><label>账单编号 / 本地凭据引用<input value={form.evidence_ref} onChange={e=>setForm({...form,evidence_ref:e.target.value})} placeholder="订单报表、结算账单或申报记录编号" required/></label><label>说明<input value={form.note} onChange={e=>setForm({...form,note:e.target.value})} placeholder="差异原因或口径说明"/></label><label>录入 / 修订人<input value={form.changed_by} onChange={e=>setForm({...form,changed_by:e.target.value})} placeholder="操作者姓名" required/></label><button className="primary-button" disabled={busy}>{busy?'保存中…':editing?'保存修订':'登记本期汇总'}</button></form>
  <div className="panel finance-panel"><div className="panel-heading"><div><h3>平台与店铺明细</h3><p>对照结算、银行到账、账内收入及税务申报。</p></div><span className="table-count">{data?.record_count||0} 条</span></div>{data?.records.map(row=><article className="platform-income-card" key={row.id}><div className="panel-heading"><div><strong>{row.platform} · {row.store_name}</strong><small>凭据：{row.evidence_ref} · 更新人：{row.updated_by} · {row.updated_at}</small></div><button className="secondary-button" onClick={()=>edit(row)}>修订</button></div><div className="platform-income-values"><span>净额 <strong>{row.platform_net_amount}</strong></span><span>应结算 <strong>{row.expected_settlement_amount}</strong></span><span>实际结算 <strong>{row.settlement_amount}</strong></span><span>结算差额 <strong className={Number(row.settlement_difference)===0?'good':'bad'}>{row.settlement_difference}</strong></span><span>银行差额 <strong className={row.bank_difference===null?'':Number(row.bank_difference)===0?'good':'bad'}>{row.bank_difference??'未录入'}</strong></span><span>申报差额 <strong>{row.declaration_difference??'未录入'}</strong></span></div>{row.note&&<small>{row.note}</small>}</article>)}{!data?.records.length&&<div className="empty-state"><FileSpreadsheet size={22}/><strong>本期尚无平台对账</strong><span>从平台订单/交易报表汇总客户支付金额，退款另计；结算账单与银行到账单独核对。</span></div>}</div></div><p className="report-caveat">支持手工登记和月度汇总 CSV 导入；没有连接电商平台或税务系统。季度申报销售额请在说明中注明其申报所属期间；CSV 入口不导入逐笔订单明细。</p></div>
}

function FinanceWorkspace({projects,openItems,expenses,bankRows,invoices,journalEntries,operatingReport,currentPeriod,refresh,focus}:{projects:ProjectRow[];openItems:OpenItem[];expenses:ExpenseRow[];bankRows:BankRow[];invoices:InvoiceRow[];journalEntries:JournalEntry[];operatingReport:OperatingReport|null;currentPeriod:string;refresh:()=>Promise<void>;focus:'bank'|'items'|'invoices'|'expenses'|'journals'}) {
  const [section,setSection]=useState<'bank'|'items'|'invoices'|'expenses'|'journals'|'reports'|'platform'>(focus);useEffect(()=>setSection(focus),[focus]);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [selected,setSelected]=useState<BankRow|null>(null);const [allocations,setAllocations]=useState<Record<string,string>>({});const [unclassifiedAmount,setUnclassifiedAmount]=useState('');const [accounts,setAccounts]=useState<ChartAccount[]>([]);const [adjustment,setAdjustment]=useState({posted_on:new Date().toLocaleDateString('sv-SE'),source_key:'',description:'',business_line:'corporate',entity_code:'main',project_code:''});const [adjustmentLines,setAdjustmentLines]=useState([{account:'',debit:'',credit:''},{account:'',debit:'',credit:''}])
  useEffect(()=>{if(section==='journals')void fetch('/api/accounts').then(response=>response.json()).then(data=>setAccounts(data.filter((row:ChartAccount)=>row.active))).catch(()=>setAccounts([]))},[section])
  async function send(path:string,payload:unknown){setError('');setBusy(true);try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||'操作未完成');await refresh();return data}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用');return null}finally{setBusy(false)}}
  const allocationMatches=selected?openItems.filter(x=>x.direction===(selected.direction==='in'?'receivable':'payable')&&x.currency===selected.currency&&Number(x.original_amount)>Number(x.settled_amount)):[];const allocationTargets=allocationMatches.filter(x=>Boolean(x.original_amount_cny));const unvaluedTargets=allocationMatches.filter(x=>!x.original_amount_cny)
  const enteredTotal=Object.values(allocations).reduce((sum,value)=>sum+(Number(value)||0),0)+(Number(unclassifiedAmount)||0)
  const targetOverdrawn=allocationTargets.some(item=>Number(allocations[item.id]||0)>Number(item.original_amount)-Number(item.settled_amount))
  async function submitAllocations(){if(!selected||enteredTotal<=0||enteredTotal>Number(selected.remaining_amount)||targetOverdrawn)return;const parts=[...allocationTargets.filter(item=>Number(allocations[item.id])>0).map(item=>({target_type:item.direction,target_id:item.id,amount:allocations[item.id]})),...(Number(unclassifiedAmount)>0?[{target_type:'unclassified',amount:unclassifiedAmount}]:[])];const result=await send('/api/bank/allocate',{bank_transaction_id:selected.id,allocations:parts});if(result){setSelected(null);setAllocations({});setUnclassifiedAmount('')}}
  return <section className="finance-workspace"><div className="workspace-tabs">{(['bank','items','invoices','expenses','journals','reports','platform'] as const).map((key,index)=><button key={key} className={section===key?'active':''} onClick={()=>setSection(key)}>{['银行流水','应收 / 应付','发票管理','经营费用','会计分录','经营报表','平台收入核对'][index]}</button>)}<span className="connection ok">流水、票据与业务单据分开记录</span></div>{error&&<div className="form-error finance-error">{error}</div>}
{section==='bank'&&<><div className="panel finance-panel"><div className="panel-heading"><div><h2>银行流水</h2><p>资金流水只记资金事实；认领往来不重复确认损益。</p></div></div><BankImportPanel send={send}/><BankAccountCoverage period={currentPeriod} send={send}/><div className="data-table"><div className="data-head bank-head"><span>日期 / 账户</span><span>流水号 / 摘要</span><span>方向</span><span>金额 / 余额</span><span>现金流分类 / 操作</span></div>{bankRows.map(row=><div className="data-row bank-row" key={row.id}><span><strong>{row.transaction_on}</strong><small>{row.account_name}</small></span><span><strong>{row.bank_reference||'无流水号'}</strong><small>{row.description||'无摘要'}</small></span><span>{row.direction==='in'?'收款':'付款'}</span><span>{row.currency} {row.amount}<small>剩余 {row.currency} {row.remaining_amount} · CNY {row.remaining_base_amount_cny||'未估值'}</small></span><div className="bank-row-actions"><BankCashFlowControl bank={row} send={send}/><button className="secondary-button" disabled={Number(row.remaining_amount)<=0} onClick={()=>{setSelected(row);setAllocations({});setUnclassifiedAmount('')}}>分配</button></div></div>)}{!bankRows.length&&<div className="empty-state"><ArrowDownLeft size={22}/><strong>暂无银行流水</strong><span>导入 CSV 后可分配至往来单据或暂挂待分类。</span></div>}</div></div>{selected&&<div className="allocation-box panel"><div className="panel-heading"><div><h2>流水认领：{selected.bank_reference||selected.id.slice(0,8)}</h2><p>{selected.description} · 可分配 {selected.currency} {selected.remaining_amount}</p></div><button className="secondary-button" onClick={()=>setSelected(null)}>取消</button></div>{!selected.base_amount_cny&&<BankFxReview bank={selected} send={send} onComplete={()=>setSelected(null)}/>}<div className="allocation-targets">{unvaluedTargets.map(item=><OpenItemFxReview key={item.id} item={item} send={send} refresh={refresh}/>)}{allocationTargets.map(item=><label className="allocation-target allocation-entry" key={item.id}><span><strong>{item.direction==='receivable'?'应收':'应付'} · {item.counterparty}</strong><small>{item.source_type} · CNY {item.original_amount_cny}</small></span><input type="number" min="0" step="0.01" value={allocations[item.id]||''} onChange={e=>setAllocations({...allocations,[item.id]:e.target.value})}/></label>)}<label className="allocation-target allocation-entry"><span><strong>暂挂待分类</strong><small>不推测为收入或费用</small></span><input type="number" min="0" step="0.01" value={unclassifiedAmount} onChange={e=>setUnclassifiedAmount(e.target.value)}/></label></div><div className="allocation-summary"><span>本次分配 {enteredTotal.toFixed(2)} / 可用 {selected.remaining_amount}</span><button className="primary-button" disabled={busy||!selected.base_amount_cny||enteredTotal<=0||enteredTotal>Number(selected.remaining_amount)||targetOverdrawn} onClick={()=>void submitAllocations()}>{busy?'保存中…':'确认分配'}</button></div></div>}</>}
{section==='items'&&<div className="panel finance-panel"><div className="panel-heading"><div><h2>应收与应付</h2><p>由销售确认和采购收货形成；流水认领冲抵未结余额。</p></div></div><div className="data-table">{openItems.map(item=><div className="data-row item-row" key={item.id}><span><strong>{item.direction==='receivable'?'应收':'应付'} · {item.counterparty}</strong>{item.currency!=='CNY'&&!item.original_amount_cny&&<OpenItemFxReview item={item} send={send} refresh={refresh}/>}</span><span>{item.source_type}</span><span>{item.currency} {item.original_amount}<small>CNY {item.original_amount_cny||'待复核'}</small></span><span>已结 {item.currency} {item.settled_amount}</span><span>未结 {item.currency} {(Number(item.original_amount)-Number(item.settled_amount)).toFixed(2)}</span></div>)}{!openItems.length&&<div className="empty-state"><WalletCards size={22}/><strong>暂无往来余额</strong></div>}</div></div>}
{section==='expenses'&&<ExpenseWorkspace expenses={expenses} projects={projects} period={currentPeriod} refresh={refresh}/>}
{section==='platform'&&<PlatformIncomeWorkspace period={currentPeriod}/>}
{section==='journals'&&<div className="journal-workspace"><div className="panel finance-panel journal-adjustment"><div className="panel-heading"><div><h2>新增调整凭证</h2><p>仅补记/更正账务；已过账凭证不可覆盖。CNY，借贷必须相等。</p></div></div><form onSubmit={async event=>{event.preventDefault();const result=await send('/api/journals/adjustments',{...adjustment,project_code:adjustment.project_code||null,lines:adjustmentLines.map(line=>({...line,debit:line.debit||'0',credit:line.credit||'0'}))});if(result){setAdjustment({...adjustment,source_key:crypto.randomUUID(),description:''});setAdjustmentLines([{account:'',debit:'',credit:''},{account:'',debit:'',credit:''}])}}}><div className="form-split"><label>日期<input type="date" value={adjustment.posted_on} onChange={event=>setAdjustment({...adjustment,posted_on:event.target.value})} required/></label><label>凭证说明<input value={adjustment.description} onChange={event=>setAdjustment({...adjustment,description:event.target.value})} maxLength={500} required/></label></div><div className="form-split"><label>主体编码<input value={adjustment.entity_code} onChange={event=>setAdjustment({...adjustment,entity_code:event.target.value})} required/></label><label>核算维度<select value={adjustment.business_line} onChange={event=>setAdjustment({...adjustment,business_line:event.target.value})}><option value="corporate">公司</option><option value="coffee">咖啡</option><option value="bike">自行车</option><option value="exhibition">展会</option></select></label></div><label>项目编码（可选）<input value={adjustment.project_code} onChange={event=>setAdjustment({...adjustment,project_code:event.target.value})}/></label><div className="adjustment-line-head"><span>会计科目</span><span>借方 CNY</span><span>贷方 CNY</span><span></span></div>{adjustmentLines.map((line,index)=><div className="adjustment-line" key={index}><select aria-label={`第 ${index+1} 行科目`} value={line.account} onChange={event=>setAdjustmentLines(adjustmentLines.map((item,i)=>i===index?{...item,account:event.target.value}:item))}><option value="">选择科目</option>{accounts.map(account=><option key={account.account_code} value={account.account_code}>{account.account_code} · {account.account_name}</option>)}</select><input aria-label={`第 ${index+1} 行借方`} type="number" min="0" step="0.01" value={line.debit} onChange={event=>setAdjustmentLines(adjustmentLines.map((item,i)=>i===index?{...item,debit:event.target.value,credit:event.target.value?'':'0'}:item))}/><input aria-label={`第 ${index+1} 行贷方`} type="number" min="0" step="0.01" value={line.credit} onChange={event=>setAdjustmentLines(adjustmentLines.map((item,i)=>i===index?{...item,credit:event.target.value,debit:event.target.value?'':'0'}:item))}/><button type="button" className="icon-button" disabled={adjustmentLines.length<=2} onClick={()=>setAdjustmentLines(adjustmentLines.filter((_,i)=>i!==index))} aria-label="删除分录行"><X size={15}/></button></div>)}<button type="button" className="text-link" onClick={()=>setAdjustmentLines([...adjustmentLines,{account:'',debit:'',credit:''}])}>＋ 添加分录行</button><label>来源凭证键<input value={adjustment.source_key} onChange={event=>setAdjustment({...adjustment,source_key:event.target.value})} maxLength={160} required/></label><button className="primary-button" disabled={busy||!accounts.length}>{busy?'保存中…':'确认过账'}</button></form></div><div className="panel finance-panel journal-panel"><div className="panel-heading"><div><h2>会计分录</h2><p>由业务事实和经复核的调整凭证形成，按 CNY 本位币记录。</p></div><button className="secondary-button" onClick={()=>void refresh()}>刷新</button></div>{journalEntries.map(entry=><article className="journal-entry" key={entry.id}><div className="journal-entry-head"><span><strong>{entry.posted_on} · {entry.source_type}</strong><small>{entry.memo||entry.business_line+' / '+entry.entity_code} · {entry.source_id}</small></span><span>借 {entry.currency} {entry.debit_total} / 贷 {entry.currency} {entry.credit_total}</span></div><div className="journal-lines">{entry.lines.map((line,index)=><div className="journal-line" key={index}><span>{line.account}</span><span>{Number(line.debit)?line.debit:'—'}</span><span>{Number(line.credit)?line.credit:'—'}</span></div>)}</div></article>)}{!journalEntries.length&&<div className="empty-state"><FileCheck2 size={22}/><strong>暂无会计分录</strong><span>业务凭证会在过账后显示在此处。</span></div>}</div></div>}
{section==='reports'&&<OperatingReportView report={operatingReport} period={currentPeriod} send={send}/>}
{section==='invoices'&&<><EvidenceArchivePanel/><div className="invoice-layout"><div className="panel finance-panel"><div className="panel-heading"><div><h2>发票台账</h2><p>内部认领与税务用途/认证状态分开维护。</p></div></div>{invoices.map(invoice=><InvoiceCard key={invoice.id} invoice={invoice} openItems={openItems} send={send} refresh={refresh}/>)}{!invoices.length&&<div className="empty-state"><FileCheck2 size={22}/><strong>暂无发票</strong></div>}</div><InvoiceForm send={send}/></div></>}</section>
}
const expenseCategoryLabels:Record<string,string>={marketing:'市场推广',rent:'租赁',logistics:'物流仓储',software:'软件服务',travel:'差旅',utilities:'水电通信',professional_services:'专业服务',booth_rental:'展位租赁',event_fee:'展会服务费',sample_cost:'样品费用',decoration:'展位搭建',accommodation:'住宿',other:'其他'}
function trialBalanceAccountLabel(account:string){if(account.startsWith('operating_expense:'))return `经营费用 · ${expenseCategoryLabels[account.split(':',2)[1]]||account.split(':',2)[1]}`;const labels:Record<string,string>={bank:'银行存款（已过账分配）',accounts_receivable:'应收账款',accounts_payable:'应付账款',inventory:'存货', 'inventory:bike':'自行车存货',supplier_advances:'供应商预付款',unclassified_receipts:'待分类收款',unclassified_payments:'待分类付款',sales_revenue:'销售收入',cost_of_goods_sold:'主营业务成本',realized_fx_gain:'已实现汇兑收益',realized_fx_loss:'已实现汇兑损失'};return labels[account]||account}
function ExpenseReconciliationPanel({period,expenses,refresh}:{period:string;expenses:ExpenseRow[];refresh:()=>Promise<void>}){
  const [data,setData]=useState<ExpenseReconciliation|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [actor,setActor]=useState('');const [targets,setTargets]=useState<Record<string,string>>({});const [editing,setEditing]=useState<ExpenseReconSource|null>(null);const [sourceForm,setSourceForm]=useState({source_id_key:'',source_name:'',source_total:'0.00',evidence_ref:'',scope_note:''});const [coverageNote,setCoverageNote]=useState('')
  async function load(){const response=await fetch(`/api/expenses/reconciliation?period=${period}`);const value=await response.json();if(!response.ok)throw new Error(value.error||'费用核对状态读取失败');setData(value as ExpenseReconciliation)}
  useEffect(()=>{setData(null);void load().catch(reason=>setError(reason instanceof Error?reason.message:'本地 API 不可用'))},[period,expenses.length])
  async function post(path:string,payload:unknown){setBusy(true);setError('');try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error||'费用核对操作失败');await refresh();await load();return result}catch(reason){setError(reason instanceof Error?reason.message:'本地 API 不可用');return null}finally{setBusy(false)}}
  async function saveSource(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!actor.trim()){setError('请填写当前操作者姓名');return}const result=await post('/api/expenses/reconciliation/source',{...sourceForm,source_id:editing?.id||null,period,changed_by:actor.trim(),action_key:crypto.randomUUID()});if(result){setEditing(null);setSourceForm({source_id_key:'',source_name:'',source_total:'0.00',evidence_ref:'',scope_note:''})}}
  async function linkExpense(expense:ExpenseReconLine){const source_id=targets[expense.id]||expense.source_id;if(!source_id||!actor.trim())return;await post('/api/expenses/reconciliation/link',{expense_id:expense.id,source_id,changed_by:actor.trim(),action_key:crypto.randomUUID()})}
  async function confirmCoverage(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!actor.trim()){setError('请填写当前操作者姓名');return}await post('/api/expenses/reconciliation/coverage',{period,note:coverageNote,confirmed_by:actor.trim(),action_key:crypto.randomUUID()})}
  return <section className="panel finance-panel expense-reconciliation"><div className="panel-heading"><div><h2>{period} 费用完整性核对</h2><p>登记外部费用来源总额，将每笔账内费用关联到来源，并确认来源清单完整。</p></div><strong className={data?.complete?'good':'bad'}>{data?.complete?'来源金额已核平':'核对未完成'}</strong></div>{data&&<><div className="trial-balance-summary"><span>外部来源 {data.source_count} 个</span><span>账内费用 {data.expense_count} 笔</span><span>未关联 {data.unlinked_expense_count} 笔</span><span>来源差额 {data.mismatched_source_count} 个</span><strong className={data.coverage_confirmed?'good':'bad'}>完整性声明：{data.coverage_confirmed?'当前有效':'未确认或已过期'}</strong></div><div className="trial-balance-empty">{data.scope}</div></>}{error&&<div className="form-error">{error}</div>}<label className="recon-operator">操作者姓名（手工声明，未认证）<input value={actor} onChange={event=>setActor(event.target.value)} placeholder="录入核对人姓名"/></label><div className="expense-recon-grid"><form className="receive-form" onSubmit={saveSource}><div className="panel-heading"><div><h3>{editing?'修改外部来源':'登记外部来源'}</h3><p>金额须为该来源本期发生的 CNY 费用总额。</p></div>{editing&&<button type="button" className="secondary-button" onClick={()=>{setEditing(null);setSourceForm({source_id_key:'',source_name:'',source_total:'0.00',evidence_ref:'',scope_note:''})}}>取消</button>}</div><label>来源稳定键<input value={sourceForm.source_id_key} disabled={Boolean(editing)} onChange={event=>setSourceForm({...sourceForm,source_id_key:event.target.value})} placeholder="如：corporate-card" required/></label><label>来源名称<input value={sourceForm.source_name} onChange={event=>setSourceForm({...sourceForm,source_name:event.target.value})} placeholder="公司卡 / 报销系统 / 合同台账" required/></label><label>外部来源费用合计（CNY）<input type="number" min="0" step="0.01" value={sourceForm.source_total} onChange={event=>setSourceForm({...sourceForm,source_total:event.target.value})} required/></label><label>凭据编号或本地文件引用<input value={sourceForm.evidence_ref} onChange={event=>setSourceForm({...sourceForm,evidence_ref:event.target.value})} placeholder="对账单编号或本地归档路径" required/></label><label>来源范围说明<input value={sourceForm.scope_note} onChange={event=>setSourceForm({...sourceForm,scope_note:event.target.value})} placeholder="包含的费用类型、日期范围等" required/></label><button className="primary-button" disabled={busy||!actor.trim()}>{busy?'保存中…':editing?'保存来源修订':'登记来源'}</button></form><div className="expense-source-list"><h3>外部来源核对</h3>{data?.sources.map(source=><article className="expense-source-card" key={source.id}><div><strong>{source.source_name} · {source.source_key}</strong><small>凭据 {source.evidence_ref} · {source.scope_note}</small><small>外部 CNY {source.source_total} · 已关联 CNY {source.linked_total}</small></div><strong className={source.reconciled?'good':'bad'}>{source.reconciled?'核平':`差额 CNY ${source.difference}`}</strong><button className="secondary-button" onClick={()=>{setEditing(source);setSourceForm({source_id_key:source.source_key,source_name:source.source_name,source_total:source.source_total,evidence_ref:source.evidence_ref,scope_note:source.scope_note})}}>修改</button></article>)}{!data?.sources.length&&<div className="empty-inline">尚未登记来源；若本期确无费用来源，登记完整性声明时说明原因。</div>}</div></div><div className="expense-source-list expense-source-links"><h3>逐笔关联费用</h3>{data?.expenses.map(expense=><article className="expense-source-card" key={expense.id}><div><strong>{expense.incurred_on} · {expense.counterparty} · CNY {expense.amount}</strong><small>{expense.memo||expense.category} · {expense.source_name||'尚未关联外部来源'}</small></div><select aria-label={`费用 ${expense.id} 的外部来源`} value={targets[expense.id]??expense.source_id??''} onChange={event=>setTargets({...targets,[expense.id]:event.target.value})}><option value="">选择来源</option>{data.sources.map(source=><option key={source.id} value={source.id}>{source.source_name} · {source.source_key}</option>)}</select><button className="secondary-button" disabled={busy||!(targets[expense.id]||expense.source_id)||!actor.trim()} onClick={()=>void linkExpense(expense)}>{expense.source_id?'更新来源关联':'关联来源'}</button></article>)}{!data?.expenses.length&&<div className="empty-inline">本期尚无已登记费用。</div>}</div><form className="expense-coverage-form" onSubmit={confirmCoverage}><div><h3>确认本期来源清单完整</h3><p>确认覆盖报销、银行卡、合同、员工垫付及其他费用来源。清单或费用数变化后需重新确认。</p></div><label>核对说明<textarea value={coverageNote} onChange={event=>setCoverageNote(event.target.value)} placeholder="列出已检查的来源，并说明未包含来源或本期无费用的依据" required/></label><button className="primary-button" disabled={busy||!actor.trim()}>{busy?'保存中…':'确认来源清单'}</button></form></section>
}

function ExpenseWorkspace({expenses,projects,period,refresh}:{expenses:ExpenseRow[];projects:ProjectRow[];period:string;refresh:()=>Promise<void>}){return <><ExpenseReconciliationPanel period={period} expenses={expenses} refresh={refresh}/><div className="expense-layout"><div className="panel finance-panel"><div className="panel-heading"><div><h2>经营费用台账</h2><p>按费用发生日确认费用并形成应付；公共费用可分批归属至项目，分摊只重分类，不重复增加公司费用。</p></div><span className="table-count">{expenses.length} 笔</span></div>{expenses.length?<div className="expense-table"><div className="expense-head"><span>发生日 / 类别</span><span>往来单位</span><span>摘要 / 来源键</span><span>金额</span></div>{expenses.map(item=><div className="expense-row" key={item.id}><span><strong>{item.incurred_on}</strong><small>{expenseCategoryLabels[item.category]||item.category} · {item.business_line} / {item.entity_code}{item.project_code?` · ${item.project_code}`:''}</small></span><span>{item.counterparty}</span><span><strong>{item.memo||'—'}</strong><small>{item.source_key}</small></span><span>{item.currency} {item.amount}{!item.project_code&&<><small>已分摊 CNY {item.allocated_amount} · 未分摊 CNY {item.unallocated_amount}</small>{item.allocations.map(allocation=><div className="expense-allocation-detail" key={allocation.id}><small>{allocation.allocated_on} · {allocation.project_code} {allocation.project_name} · {allocation.business_line} · 原分摊 CNY {allocation.amount} · 已撤销 {allocation.reversed_amount} · 可撤销 {allocation.reversible_amount}</small>{Number(allocation.reversible_amount)>0&&<ExpenseAllocationReversalForm allocation={allocation} refresh={refresh}/>}</div>)}{Number(item.unallocated_amount)>0&&<ExpenseAllocationForm expense={item} projects={projects} refresh={refresh}/>}</>}</span></div>)}</div>:<div className="empty-state"><WalletCards size={22}/><strong>尚无已登记经营费用</strong><span>录入费用发生事实后，系统会同时生成应付和权责发生制分录。</span></div>}</div><ExpenseForm refresh={refresh}/></div></>}

function ExpenseAllocationReversalForm({allocation,refresh}:{allocation:ExpenseAllocation;refresh:()=>Promise<void>}){
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [sourceKey,setSourceKey]=useState(()=>crypto.randomUUID())
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget).entries());setBusy(true);setError('');try{const response=await fetch(`/api/expenses/allocations/${allocation.id}/reverse`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,source_key:sourceKey,changed_by:'local-unverified'})});const result=await response.json();if(!response.ok)throw new Error(result.error||'撤销分摊失败');setSourceKey(crypto.randomUUID());await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  return <form className="expense-allocation-form allocation-reversal-form" onSubmit={event=>void submit(event)}><input name="amount" type="number" min="0.01" max={allocation.reversible_amount} step="0.01" defaultValue={allocation.reversible_amount} required/><input name="reversed_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/><button className="secondary-button" disabled={busy}>{busy?'撤销中…':'撤销分摊'}</button>{error&&<small className="form-error">{error}</small>}</form>
}

function ExpenseAllocationForm({expense,projects,refresh}:{expense:ExpenseRow;projects:ProjectRow[];refresh:()=>Promise<void>}){
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [sourceKey,setSourceKey]=useState(()=>crypto.randomUUID())
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch(`/api/expenses/${expense.id}/allocations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,amount:String(values.amount),source_key:sourceKey})});const result=await response.json();if(!response.ok)throw new Error(result.error||'项目费用分摊失败');form.reset();setSourceKey(crypto.randomUUID());await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  return <form className="expense-allocation-form" onSubmit={event=>void submit(event)}><select name="project_code" aria-label="分摊项目" required defaultValue=""><option value="" disabled>分摊至项目</option>{projects.filter(project=>project.entity_code===expense.entity_code).map(project=><option key={project.code} value={project.code}>{project.code} · {project.name}</option>)}</select><select name="business_line" aria-label="项目业务线" required defaultValue="exhibition"><option value="exhibition">展会</option><option value="coffee">咖啡</option><option value="bike">自行车</option></select><input name="amount" type="number" min="0.01" max={expense.unallocated_amount} step="0.01" placeholder={`最多 ${expense.unallocated_amount}`} required/><input name="allocated_on" type="date" defaultValue={new Date().toLocaleDateString('sv-SE')} required/><button className="secondary-button" disabled={busy||projects.every(project=>project.entity_code!==expense.entity_code)}>{busy?'分摊中…':'确认分摊'}</button>{error&&<small className="form-error">{error}</small>}</form>
}
function ExpenseForm({refresh,defaultBusinessLine='corporate',defaultEntityCode='main',defaultProjectCode,lockDimensions=false}:{refresh:()=>Promise<void>;defaultBusinessLine?:string;defaultEntityCode?:string;defaultProjectCode?:string;lockDimensions?:boolean}) {
  const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setBusy(true);setError('');try{const response=await fetch('/api/expenses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,currency:'CNY',business_line:defaultBusinessLine,entity_code:defaultEntityCode,project_code:defaultProjectCode??data.project_code??null})});const result=await response.json();if(!response.ok)throw new Error(result.error||'费用登记失败');form.reset();await refresh()}catch(e){setError(e instanceof Error?e.message:'费用保存失败')}finally{setBusy(false)}}
  return <form className="panel purchase-form expense-form" onSubmit={submit}><h2>登记经营费用</h2><p>按发生日确认损益并形成应付；税票和税务状态另行管理。</p><label>费用发生日期<input type="date" name="incurred_on" defaultValue={new Date().toLocaleDateString('sv-SE')} required/></label><label>费用类别<select name="category" required>{Object.entries(expenseCategoryLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label><label>业务线<select name="business_line" defaultValue={defaultBusinessLine} disabled={lockDimensions} required><option value="corporate">公司共用</option><option value="coffee">咖啡业务</option><option value="bike">自行车业务</option><option value="exhibition">展会项目</option></select></label><label>经营主体编码<input name="entity_code" defaultValue={defaultEntityCode} disabled={lockDimensions} required/></label><label>项目编码（可选）<input name="project_code" defaultValue={defaultProjectCode||''} disabled={lockDimensions}/></label><label>往来单位<input name="counterparty" required placeholder="供应商或员工"/></label><label>确认费用金额（CNY）<input name="amount" inputMode="decimal" min="0.01" step="0.01" required placeholder="0.00"/></label><label>费用摘要<input name="memo" placeholder="例如：展位服务费"/></label><label>来源唯一键<input name="source_key" required placeholder="报销单号、合同号或凭证行号"/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy?'保存中…':'确认费用并生成应付'}</button></form>
}

function OpeningBalanceForm({send,onComplete}:{send:(path:string,payload:unknown)=>Promise<unknown>;onComplete:()=>Promise<void>}) {
  const [rows,setRows]=useState([{account:'bank',debit:'',credit:''},{account:'accounts_receivable',debit:'',credit:''},{account:'inventory',debit:'',credit:''},{account:'accounts_payable',debit:'',credit:''},{account:'retained_earnings',debit:'',credit:''}]);const [asOf,setAsOf]=useState('');const [entity,setEntity]=useState('main');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const accounts=rows.filter(row=>Number(row.debit)>0||Number(row.credit)>0);const debit=accounts.reduce((sum,row)=>sum+(Number(row.debit)||0),0);const credit=accounts.reduce((sum,row)=>sum+(Number(row.credit)||0),0);if(accounts.length<2||Math.abs(debit-credit)>0.005){setError('请至少录入两个非零科目，并确保借贷合计相等。');return}setBusy(true);setError('');const result=await send('/api/opening-balances',{as_of:asOf,entity_code:entity,source_key:`opening:${entity}:${asOf}`,accounts});if(result)await onComplete();setBusy(false)}
  return <form className="panel opening-balance-form" onSubmit={event=>void submit(event)}><div className="panel-heading"><div><h2>导入账套期初余额</h2><p>仅支持首次导入；日期必须早于系统内第一张业务凭证。</p></div></div><div className="form-split"><label>期初日期<input type="date" value={asOf} onChange={event=>setAsOf(event.target.value)} required/></label><label>经营主体编码<input value={entity} onChange={event=>setEntity(event.target.value)} required/></label></div><div className="opening-balance-lines">{rows.map((row,index)=><div className="opening-balance-line" key={index}><input aria-label="会计科目编码" placeholder="科目编码" value={row.account} onChange={event=>setRows(rows.map((item,i)=>i===index?{...item,account:event.target.value}:item))}/><input aria-label="借方余额" type="number" min="0" step="0.01" placeholder="借方余额" value={row.debit} onChange={event=>setRows(rows.map((item,i)=>i===index?{...item,debit:event.target.value,credit:event.target.value?'':'0'}:item))}/><input aria-label="贷方余额" type="number" min="0" step="0.01" placeholder="贷方余额" value={row.credit} onChange={event=>setRows(rows.map((item,i)=>i===index?{...item,credit:event.target.value,debit:event.target.value?'':'0'}:item))}/><button type="button" className="secondary-button" onClick={()=>setRows(rows.filter((_,i)=>i!==index))}>移除</button></div>)}</div><div className="opening-balance-actions"><button type="button" className="secondary-button" onClick={()=>setRows([...rows,{account:'',debit:'',credit:''}])}>添加科目</button><span>借方合计 {rows.reduce((sum,row)=>sum+(Number(row.debit)||0),0).toFixed(2)} · 贷方合计 {rows.reduce((sum,row)=>sum+(Number(row.credit)||0),0).toFixed(2)}</span></div>{error&&<div className="form-error">{error}</div>}<p className="report-caveat">请依据已复核的期初试算表录入，包含真实期初权益平衡项。导入后不可删除或覆盖，错误需以调整凭证更正。</p><button className="primary-button" disabled={busy||!asOf}>{busy?'导入中…':'确认导入期初余额'}</button></form>
}

function BalanceSheetReportView({period}:{period:string}){const [data,setData]=useState<BalanceSheet|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);useEffect(()=>{let cancelled=false;const [year,month]=period.split('-').map(Number);const asOf=new Date(year,month,0).toLocaleDateString('sv-SE');setBusy(true);setError('');fetch('/api/reports/balance-sheet?as_of='+asOf).then(async response=>{const value=await response.json();if(!response.ok)throw new Error(value.error||'资产负债表生成失败');if(!cancelled)setData(value as BalanceSheet)}).catch(reason=>{if(!cancelled)setError(reason instanceof Error?reason.message:'本地 API 不可用')}).finally(()=>{if(!cancelled)setBusy(false)});return()=>{cancelled=true}},[period]);if(busy)return <div className="empty-inline">正在生成截至 {period} 的资产负债表…</div>;if(error)return <div className="form-error">{error}</div>;if(!data)return null;const sections:Array<[string,BalanceSheet['assets']]>=[['资产',data.assets],['负债',data.liabilities],['权益',data.equity]];return <div className="balance-sheet-view"><div className="trial-balance-summary"><span>截止日 {data.as_of}</span><strong className={data.complete?'good':'bad'}>{data.classification_complete&&data.balanced?'总账已分类且平衡':'不完整 · 仅供核对'}</strong><span>资产 CNY {data.total_assets}</span><span>负债及权益 CNY {data.liabilities_and_equity}</span><span>差额 CNY {data.difference}</span></div>{!data.complete&&<div className="trial-balance-empty">本表按当前科目映射汇总系统总账。期初余额、暂挂科目、未映射科目或子账核对缺口会使结果不完整；请勿作为法定报表或报税依据。{data.opening_balances_as_of?` 已载入期初余额（${data.opening_balances_as_of}）。`:''}</div>}<div className="balance-sheet-section"><h3>子账与总账控制科目核对</h3>{([['应收账款',data.subledger_reconciliation.accounts_receivable],['应付账款',data.subledger_reconciliation.accounts_payable],['存货',data.subledger_reconciliation.inventory]] as const).map(([label,item])=><div className="reconciliation-row" key={label}><span>{label}<small>总账 CNY {item.general_ledger} · 子账 CNY {item.subledger}</small></span><strong className={Math.abs(Number(item.difference))<0.01?'good':'bad'}>差额 CNY {item.difference}</strong></div>)}<small className="reconciliation-note">不可追溯往来 {data.subledger_reconciliation.untraceable_open_items} · 未估值往来 {data.subledger_reconciliation.unvalued_open_items} · 未估值核销 {data.subledger_reconciliation.unvalued_settlements} · 未估值库存流水 {data.subledger_reconciliation.unvalued_inventory_movements}</small></div>{sections.map(([title,rows])=><div className="balance-sheet-section" key={title}><h3>{title}</h3>{rows.map(row=><div className="report-line" key={row.account}><span>{row.name} <small>{row.account}</small></span><strong>CNY {row.balance}</strong></div>)}<div className="report-line report-total"><span>{title}小计</span><strong>CNY {title==='资产'?data.total_assets:title==='负债'?data.total_liabilities:data.total_equity}</strong></div></div>)}<div className="balance-sheet-section"><h3>本期及累计损益转入权益</h3><div className="report-line report-total"><span>损益净额</span><strong>CNY {data.total_current_earnings}</strong></div></div>{(data.suspense.length>0||data.unmapped_accounts.length>0)&&<div className="balance-sheet-section"><h3>待分类 / 未映射科目（不计入上方分类合计）</h3>{[...data.suspense,...data.unmapped_accounts.map(row=>({account:row.account,name:'未映射科目',balance:row.balance}))].map(row=><div className="report-line" key={row.account}><span>{row.name} · {row.account}</span><strong>CNY {row.balance}</strong></div>)}</div>}<p className="report-caveat">{data.scope}</p></div>}

function CashFlowReportView({period}:{period:string}){const [data,setData]=useState<CashFlow|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);useEffect(()=>{let cancelled=false;const [year,month]=period.split('-').map(Number);const from=period+'-01';const to=new Date(year,month,0).toLocaleDateString('sv-SE');setBusy(true);setError('');fetch('/api/reports/cash-flow?from='+from+'&to='+to).then(async response=>{const value=await response.json();if(!response.ok)throw new Error(value.error||'现金流量表生成失败');if(!cancelled)setData(value as CashFlow)}).catch(reason=>{if(!cancelled)setError(reason instanceof Error?reason.message:'本地 API 不可用')}).finally(()=>{if(!cancelled)setBusy(false)});return()=>{cancelled=true}},[period]);if(busy)return <div className="empty-inline">正在汇总 {period} 银行现金流…</div>;if(error)return <div className="form-error">{error}</div>;if(!data)return null;const labels:Record<keyof CashFlow['categories'],string>={operating:'经营活动',investing:'投资活动',financing:'筹资活动',transfer:'内部转账（单列，不计公司净变动）',unclassified:'待分类流水'};return <div className="cash-flow-view"><div className="trial-balance-summary"><span>期间 {data.from} 至 {data.to} · 流水 {data.bank_transactions} 笔</span><strong className="bad">银行流水范围 · 非完整法定报表</strong><span>已分类净变动 CNY {data.net_change_classified_cash}</span><span>期初现金 {data.opening_cash_balance?'CNY '+data.opening_cash_balance:'未提供'}</span><span>期末现金 {data.closing_cash_balance?'CNY '+data.closing_cash_balance:'未提供'}</span><span>待分类 {data.unclassified_transactions} 笔</span><span>未估值 {data.unvalued_transactions} 笔</span></div><div className="trial-balance-empty">此视图按已导入银行流水和人工现金流分类汇总。所有银行账户完成登记、逐户对账并确认流水分类之前，金额只代表系统登记范围。</div><div className="cash-flow-coverage"><h3>账户覆盖与对账</h3><div className="cash-flow-coverage-status"><span>登记账户 {data.registered_bank_accounts} 个</span><span>账户清单已确认：{data.account_inventory_confirmed?'是':'否'}</span><span>逐户核平：{data.all_registered_accounts_reconciled?'是':'否'}</span><strong className={data.bank_account_coverage_complete?'good':'bad'}>{data.bank_account_coverage_complete?'账户覆盖完整':'账户覆盖未完成'}</strong></div>{data.account_reconciliations.map(account=><div className="reconciliation-row" key={`${account.account_name}:${account.currency}`}><span>{account.account_name} · {account.currency}<small>{account.opening_balance===undefined?'未录对账单':`期初 ${account.opening_balance} · 期末 ${account.closing_balance}`}</small></span><strong className={account.reconciled?'good':'bad'}>{account.difference===null?'未核对':account.reconciled?'已核平':`差额 ${account.currency} ${account.difference}`}</strong></div>)}</div><div className="cash-flow-table"><div className="cash-flow-row cash-flow-head"><span>活动类别</span><span>现金流入</span><span>现金流出</span><span>净额</span><span>笔数</span></div>{(Object.keys(labels) as (keyof CashFlow['categories'])[]).map(key=>{const item=data.categories[key];return <div className="cash-flow-row" key={key}><span>{labels[key]}</span><span>{item.inflow}</span><span>{item.outflow}</span><strong>{item.net}</strong><span>{item.transactions}</span></div>})}<div className="cash-flow-row cash-flow-total"><span>已分类经营 / 投资 / 筹资净额</span><span>—</span><span>—</span><strong>{data.net_change_classified_cash}</strong><span>—</span></div></div><p className="report-caveat">{data.scope}</p></div>}

function OperatingReportView({report,period,send}:{report:OperatingReport|null;period:string;send:(path:string,payload:unknown)=>Promise<unknown>}) {
  const [view,setView]=useState(report);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [statement,setStatement]=useState<'income'|'trial_balance'|'balance_sheet'|'cash_flow'>('income');const [trialBalance,setTrialBalance]=useState<TrialBalance|null>(null);const [trialError,setTrialError]=useState('');const [trialBusy,setTrialBusy]=useState(false)
  useEffect(()=>setView(report),[report])
  useEffect(()=>{if(statement!=='trial_balance')return;let cancelled=false;const [year,month]=period.split('-').map(Number);const asOf=new Date(year,month,0).toLocaleDateString('sv-SE');setTrialBusy(true);setTrialError('');fetch(`/api/reports/trial-balance?as_of=${asOf}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'试算平衡表读取失败');if(!cancelled)setTrialBalance(data as TrialBalance)}).catch(e=>{if(!cancelled)setTrialError(e instanceof Error?e.message:'本地 API 不可用')}).finally(()=>{if(!cancelled)setTrialBusy(false)});return()=>{cancelled=true}},[statement,period])
  async function filter(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const fields=Object.fromEntries(new FormData(form).entries());const query=new URLSearchParams({period});for(const key of ['business_line','entity_code','project_code']){const value=String(fields[key]||'').trim();if(value)query.set(key,value)}setBusy(true);setError('');try{const response=await fetch(`/api/reports/operating?${query.toString()}`);const data=await response.json();if(!response.ok)throw new Error(data.error||'报表读取失败');setView(data)}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  const expenseProfitLabel=view?.expenses_complete?'经营利润（费用来源已核对）':'经营利润（按已登记费用）'
  const rows=[['销售收入',view?.sales_revenue],['销售成本',view?.cost_of_goods_sold],['毛利',view?.gross_profit],['已登记经营费用',view?.operating_expenses],['盘点盘盈 / 盘亏净额',view?.inventory_adjustment_net],[expenseProfitLabel,view?.operating_profit],['已实现汇兑损益（非经营）',view?.realized_fx_gain_loss]] as const
  return <div className="panel finance-panel operating-report"><div className="panel-heading"><div><h2>财务报表</h2><p>报表取自本地已过账 CNY 总账数据；期初余额及科目分类状态按账套记录显示。</p></div><span className="local-only">{statement==='income'?(view?.expenses_complete?'费用来源已核对':'登记范围内'):'系统账务范围'}</span></div><div className="report-switcher"><button className={statement==='income'?'active':''} onClick={()=>setStatement('income')}>经营损益</button><button className={statement==='trial_balance'?'active':''} onClick={()=>setStatement('trial_balance')}>试算平衡</button><button className={statement==='balance_sheet'?'active':''} onClick={()=>setStatement('balance_sheet')}>资产负债表</button><button className={statement==='cash_flow'?'active':''} onClick={()=>setStatement('cash_flow')}>现金流量表</button></div>{statement==='income'?<><div className="report-period-title">{period} 经营损益</div><form className="report-filters" onSubmit={filter}><label>业务线<select name="business_line" defaultValue=""><option value="">全部业务线</option><option value="coffee">咖啡业务</option><option value="bike">自行车业务</option><option value="exhibition">展会项目</option><option value="corporate">公司共用</option></select></label><label>主体编码<input name="entity_code" placeholder="全部主体"/></label><label>项目编码<input name="project_code" placeholder="全部项目"/></label><button className="secondary-button" disabled={busy}>{busy?'汇总中…':'应用筛选'}</button></form>{error&&<div className="form-error">{error}</div>}{view?.period===period?<><div className="report-lines">{rows.map(([label,value],index)=><div className={`report-line ${index===2||index===4?'report-total':''}`} key={label}><span>{label}</span><strong>{view.currency} {Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div>)}{Object.entries(view.operating_expenses_by_category||{}).map(([category,value])=><div className="report-line report-category" key={category}><span>　{expenseCategoryLabels[category]||category}</span><strong>{view.currency} {Number(value).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></div>)}</div><div className="trial-balance-empty">费用核对：来源 {view.expense_reconciliation_summary.source_count} 个 · 未关联 {view.expense_reconciliation_summary.unlinked_expense_count} 笔 · 金额不符 {view.expense_reconciliation_summary.mismatched_source_count} 个 · 来源清单{view.expense_reconciliation_summary.coverage_confirmed?'已确认':'未确认'}。</div></>:<div className="empty-state"><Activity size={22}/><strong>本期报表暂不可用</strong><span>确认本地 API 连接后重新载入。</span></div>}<p className="report-caveat">{view?.expenses_complete?'已登记费用与手工声明的外部来源清单逐项核对一致；来源覆盖和操作者身份尚未接入独立认证，结果仍属于内部核对。':'费用尚未完成与全部外部付款、报销及合同来源的核对，经营利润仅代表已登记范围。'}</p></>:statement==='trial_balance'?<>{trialBusy?<div className="empty-inline">正在生成截至 {period} 的试算平衡表…</div>:trialError?<div className="form-error">{trialError}</div>:trialBalance&&<>{!trialBalance.opening_balances_configured&&<OpeningBalanceForm send={send} onComplete={async()=>{const parts=period.split('-').map(Number);const asOf=new Date(parts[0],parts[1],0).toLocaleDateString('sv-SE');const response=await fetch('/api/reports/trial-balance?as_of='+asOf);const data=await response.json();if(response.ok)setTrialBalance(data as TrialBalance)}}/>}<div className="trial-balance-summary"><span>截止日 {trialBalance.as_of}</span><span>凭证行 {trialBalance.journal_lines}</span><span>借方余额合计 CNY {trialBalance.debit_balance_total}</span><span>贷方余额合计 CNY {trialBalance.credit_balance_total}</span><strong className={trialBalance.balanced?'good':'bad'}>{trialBalance.balanced?'借贷平衡':'存在差异'}</strong></div>{trialBalance.journal_lines===0&&<div className="trial-balance-empty">截至该日期没有系统内已过账的人民币凭证。当前显示的零余额仅代表系统数据为空，不代表企业实际资产、负债或权益为零。</div>}<div className="trial-balance-table"><div className="trial-balance-row trial-balance-head"><span>会计科目</span><span>借方发生额</span><span>贷方发生额</span><span>借方余额</span><span>贷方余额</span></div>{trialBalance.accounts.map(row=><div className="trial-balance-row" key={row.account}><span>{trialBalanceAccountLabel(row.account)}</span><span>{row.debit_turnover}</span><span>{row.credit_turnover}</span><strong>{row.debit_balance}</strong><strong>{row.credit_balance}</strong></div>)}<div className="trial-balance-row trial-balance-total"><span>合计</span><strong>{trialBalance.debit_turnover_total}</strong><strong>{trialBalance.credit_turnover_total}</strong><strong>{trialBalance.debit_balance_total}</strong><strong>{trialBalance.credit_balance_total}</strong></div></div><p className="report-caveat">本表仅汇总系统内截至所选月份末已过账的人民币分录及已导入的期初余额，不包含外币账簿或未过账业务。借贷平衡只证明分录算术平衡；科目类别映射和子账迁移未完成，不能视为完整法定资产负债表。</p></>}</>:statement==='balance_sheet'?<BalanceSheetReportView period={period}/>:<CashFlowReportView period={period}/>}</div>
}

type BankField='transaction_on'|'direction'|'amount'|'account_name'|'bank_reference'|'description'|'currency'|'exchange_rate'|'rate_date'|'rate_source'
type BankImportMap=Record<BankField,string>
type BankImportOutcome={created:{source_key:string}[];duplicates:string[];rejected:{row:number;source_key:string;error:string}[]}
const bankFieldLabels:Record<BankField,string>={transaction_on:'交易日期',direction:'收支方向',amount:'金额',account_name:'账户（可选）',bank_reference:'流水号（可选）',description:'摘要（可选）',currency:'币种',exchange_rate:'FX rate',rate_date:'FX rate date',rate_source:'FX rate source'}
const emptyBankMap:BankImportMap={transaction_on:'',direction:'',amount:'',account_name:'',bank_reference:'',description:'',currency:'',exchange_rate:'',rate_date:'',rate_source:''}
function normalizeBankDirection(value:string):'in'|'out'|''{const raw=value.trim().toLowerCase();if(/支出|付款|转出|借方|^借$|debit|^out$/.test(raw))return 'out';if(/收入|收款|转入|贷方|^贷$|credit|^in$/.test(raw))return 'in';return ''}
async function archiveOriginal(file:File,category:string,period:string,sourceSystem='work-os'):Promise<{id:string}>{
  const response=await fetch('/api/archive/files',{method:'POST',
    headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name),
      'X-Document-Category':category,'X-Document-Period':period,'X-Source-System':sourceSystem},body:file});
  const result=await response.json();
  if(!response.ok||!result.id)throw new Error(result.error||'原始凭证归档失败，未进行数据入账');
  return result;
}
function BankImportPanel({send}:{send:(path:string,payload:unknown)=>Promise<unknown>}){const [headers,setHeaders]=useState<string[]>([]);const [rows,setRows]=useState<string[][]>([]);const [fileName,setFileName]=useState('');const [originalFile,setOriginalFile]=useState<File|null>(null);const [map,setMap]=useState<BankImportMap>(emptyBankMap);const [outcome,setOutcome]=useState<BankImportOutcome|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  async function choose(file?:File){if(!file)return;setError('');setOutcome(null);setFileName(file.name);setOriginalFile(file);try{if(!/\.csv$/i.test(file.name))throw new Error('当前只支持 CSV；请先另存为 UTF-8 CSV。');const parsed=parseCsv(await file.text());if(parsed.length<2)throw new Error('文件需要表头和明细行。');const cols=parsed[0].map((value,index)=>value.trim().replace(/^\uFEFF/,'')||`列${index+1}`);setHeaders(cols);setRows(parsed.slice(1));const find=(names:string[])=>cols.find(h=>names.includes(h.toLowerCase()))||'';setMap({transaction_on:find(['交易日期','记账日期','日期','交易时间','date','transaction_date']),direction:find(['收支方向','方向','收支','借贷标志','type','direction']),amount:find(['金额','发生额','交易金额','amount']),account_name:find(['账户','账户名称','银行卡','account']),bank_reference:find(['流水号','交易流水号','参考号','reference','transaction_id']),description:find(['摘要','说明','交易摘要','description','memo']),currency:find(['币种','货币','currency']),exchange_rate:find(['汇率','记账汇率','exchange_rate','fx_rate']),rate_date:find(['汇率日期','rate_date']),rate_source:find(['汇率来源','rate_source','fx_source'])})}catch(e){setError(e instanceof Error?e.message:'无法读取 CSV')}}
  const prepared=rows.map((cells,index)=>{const get=(field:BankField)=>{const header=map[field];return header?cells[headers.indexOf(header)]?.trim()||'':''};const dateText=get('transaction_on');const dateOk=/^\d{4}-\d{2}-\d{2}$/.test(dateText)&&Number.isFinite(Date.parse(`${dateText}T00:00:00`))&&new Date(`${dateText}T00:00:00Z`).toISOString().slice(0,10)===dateText;const direction=normalizeBankDirection(get('direction'));const amountText=get('amount').replace(/[,¥￥\s]/g,'');const value=Number(amountText);const currency=get('currency').toUpperCase();const rateText=get('exchange_rate');const rate=currency==='CNY'?1:Number(rateText);const rateDate=get('rate_date')||dateText;const rateSource=currency==='CNY'?'functional_currency':get('rate_source');const account=get('account_name')||'未指定账户';const reference=get('bank_reference');const rowKey=reference?`bank:v2:${encodeURIComponent(account)}:${dateText}:${encodeURIComponent(reference)}`:`${fileName}:${index+2}`;const errors:string[]=[];if(!dateOk)errors.push('日期缺失或不是有效的 YYYY-MM-DD');if(!map.currency||!currency)errors.push('币种缺失');if(!direction)errors.push('收支方向无法识别');if(!amountText)errors.push('金额缺失');else if(!Number.isFinite(value)||value<=0)errors.push('金额须为正数');if(currency!=='CNY'&&(!Number.isFinite(rate)||rate<=0||!rateSource))errors.push('外币流水须提供正数汇率及汇率来源');if(currency!=='CNY'&&!/^\d{4}-\d{2}-\d{2}$/.test(rateDate))errors.push('汇率日期须为 YYYY-MM-DD');return {index,rowKey,errors,payload:{source_key:rowKey,transaction_on:dateText,account_name:get('account_name')||'未指定账户',bank_reference:get('bank_reference'),description:get('description'),direction,amount:amountText,currency,exchange_rate:String(rate),rate_date:rateDate,rate_source:rateSource}}})
  const valid=prepared.filter(row=>row.errors.length===0);const requiredMapped=Boolean(map.transaction_on&&map.direction&&map.amount&&map.currency)
  async function submit(){if(!requiredMapped){setError('请先映射交易日期、收支方向、金额和币种列。');return}if(!valid.length){setError('没有通过校验的流水行。');return}if(!originalFile){setError('请先选择原始流水文件');return}setError('');setBusy(true);try{
    const period=valid[0].payload.transaction_on.slice(0,7);
    const evidence=await archiveOriginal(originalFile,'bank',period,'finance.bank');
    const raw=await send('/api/bank/import',{archive_file_id:evidence.id,rows:valid.map(row=>row.payload)});
    if(raw)setOutcome(raw as BankImportOutcome)
  }catch(e){setError(e instanceof Error?e.message:'原件归档失败，未提交银行数据')}finally{setBusy(false)}}
  const resultFor=(key:string)=>outcome?.created.some(row=>row.source_key===key)?'已导入':outcome?.duplicates.includes(key)?'重复，已跳过':outcome?.rejected.find(row=>row.source_key===key)?.error
  return <div className="bank-import"><label className="secondary-button bank-upload">{fileName||'选择银行 CSV'}<input type="file" accept=".csv,text/csv" onChange={e=>void choose(e.target.files?.[0])}/></label>{headers.length>0&&<div className="bank-import-config"><div className="bank-import-title"><strong>字段映射 · {fileName}</strong><span>有银行流水号时按账户＋日期＋流水号防重；缺失流水号时仍需人工复核</span></div><div className="bank-mapping-grid">{(Object.keys(bankFieldLabels) as BankField[]).map(field=><label key={field}>{bankFieldLabels[field]}<select value={map[field]} onChange={e=>setMap({...map,[field]:e.target.value})}><option value="">{['account_name','bank_reference','description'].includes(field)?'未映射（使用默认值）':'请选择列'}</option>{headers.map(header=><option key={header} value={header}>{header}</option>)}</select></label>)}</div><div className="bank-import-summary"><span>共 {rows.length} 行</span><span>可导入 {valid.length}</span><span>需复核 {rows.length-valid.length}</span><button className="primary-button" disabled={busy||!requiredMapped||!valid.length} onClick={()=>void submit()}>{busy?'导入中…':'导入有效行'}</button></div>{error&&<div className="form-error">{error}</div>}<div className="bank-preview">{prepared.slice(0,30).map(row=><div className="bank-preview-row" key={`${row.rowKey}:${row.index}`}><span>第 {row.index+2} 行 · {row.payload.transaction_on||'无日期'}</span><span>{row.payload.direction==='in'?'收款':row.payload.direction==='out'?'付款':'方向未知'} · {row.payload.currency} {row.payload.amount||'无金额'}</span><span className={row.errors.length?'bad':''}>{resultFor(row.rowKey)||row.errors.join('；')||'可导入'}</span></div>)}</div>{rows.length>30&&<small className="bank-preview-more">预览前 30 行，共 {rows.length} 行。</small>}</div>}</div>
}

function InvoiceCard({invoice,openItems,send,refresh}:{invoice:InvoiceRow;openItems:OpenItem[];send:(path:string,payload:unknown)=>Promise<unknown>;refresh:()=>Promise<void>}){const [ref,setRef]=useState(invoice.tax_evidence_ref||'');const [status,setStatus]=useState(invoice.tax_status);const [targetId,setTargetId]=useState('');const [linkAmount,setLinkAmount]=useState('');const [error,setError]=useState('');async function save(){const r=await fetch('/api/invoices/tax-status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({invoice_id:invoice.id,tax_status:status,tax_evidence_ref:ref})});if(r.ok)await refresh();else{const d=await r.json();setError(d.error||'保存失败')}}const targets=openItems.filter(x=>x.direction===(invoice.direction==='sales'?'receivable':'payable')&&x.counterparty===invoice.counterparty&&x.currency===invoice.currency&&Number(x.original_amount)>Number(x.settled_amount));async function link(){if(!targetId||!linkAmount)return;const out=await send('/api/invoices/link',{invoice_id:invoice.id,target_type:invoice.direction==='sales'?'receivable':'payable',target_id:targetId,amount:linkAmount});if(out){setLinkAmount('');setTargetId('')}}return <div className="invoice-card"><div><strong>{invoice.invoice_number} · {invoice.counterparty}</strong><small>{invoice.direction==='purchase'?'进项':'销项'} · {invoice.issued_on} · {invoice.currency} {invoice.total_amount}（税额 {invoice.tax_amount}） · 汇率 {invoice.exchange_rate} / {invoice.rate_date}</small><small>内部登记不代表抵扣；已关联 {invoice.currency} {invoice.linked_amount} / {invoice.total_amount}；税务状态：{status}{ref?` · 依据 ${ref}`:''}</small>{targets.length>0&&Number(invoice.linked_amount)<Number(invoice.total_amount)&&<div className="invoice-link-controls"><select value={targetId} onChange={e=>setTargetId(e.target.value)}><option value="">选择同币种同往来单位单据</option>{targets.map(x=><option key={x.id} value={x.id}>{x.direction==='receivable'?'应收':'应付'} · {x.source_type} · 尚欠 {(Number(x.original_amount)-Number(x.settled_amount)).toFixed(2)} {x.currency}</option>)}</select><input value={linkAmount} onChange={e=>setLinkAmount(e.target.value)} inputMode="decimal" placeholder="关联金额"/><button className="secondary-button" disabled={!targetId||!linkAmount} onClick={()=>void link()}>内部关联</button></div>}</div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="pending">待核实</option><option value="eligible">符合抵扣条件</option><option value="certified_deductible">已认证可抵扣（人工确认）</option><option value="non_deductible">不得抵扣</option><option value="void">已作废</option></select><input value={ref} onChange={e=>setRef(e.target.value)} placeholder="税务确认依据编号（可选）"/><button className="secondary-button" onClick={()=>void save()}>保存状态</button>{error&&<small className="form-error">{error}</small>}</div>}
type ArchivedEvidenceRow={id:string;sha256:string;size_bytes:number;original_name:string;category:string;period:string;created_at:string}
function EvidenceArchivePanel(){
  const [rows,setRows]=useState<ArchivedEvidenceRow[]>([]);
  const [sourceFile,setSourceFile]=useState<File|null>(null);
  const [period,setPeriod]=useState(new Date().toISOString().slice(0,7));
  const [category,setCategory]=useState('input_invoice');
  const [sourceSystem,setSourceSystem]=useState('');
  const [sourceId,setSourceId]=useState('');
  const [busy,setBusy]=useState(false);
  const [status,setStatus]=useState('');
  async function load(){const r=await fetch('/api/archive/files');if(!r.ok)throw new Error('原始档案列表读取失败');setRows(await r.json() as ArchivedEvidenceRow[])}
  useEffect(()=>{void load().catch(e=>setStatus(e instanceof Error?e.message:'档案暂不可用'))},[]);
  async function upload(e:React.FormEvent<HTMLFormElement>){
    e.preventDefault();if(!sourceFile)return;setBusy(true);setStatus('');
    try{
      const result=await archiveOriginal(sourceFile,category,period,'work-os');
      if(sourceSystem.trim()&&sourceId.trim()){
        const response=await fetch('/api/archive/links',{method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify({file_id:result.id,source_system:sourceSystem.trim(),source_document_id:sourceId.trim()})});
        const linked=await response.json();
        if(!response.ok)throw new Error(linked.error||'原件已保存，但关联业务单失败');
      }
      setStatus('原始凭证已保存，SHA-256：'+result.id.slice(0,12)+'…');
      await load();
    }catch(e){setStatus(e instanceof Error?e.message:'原件归档失败')}finally{setBusy(false)}
  }
  return <div className="panel finance-panel">
    <div className="panel-heading"><div><h2>统一原始凭证档案</h2><p>银行、进销项、采购、销售原件集中保存；与发票认领、税务认证分别处理。</p></div><strong>{rows.length} 条档案记录</strong></div>
    <form onSubmit={e=>void upload(e)} className="form-split">
      <label>选择文件<input type="file" accept=".csv,.xls,.xlsx,.pdf,.ofd,.xml,.zip,.txt" required onChange={e=>setSourceFile(e.target.files?.[0]||null)}/></label>
      <label>凭证类别<select value={category} onChange={e=>setCategory(e.target.value)}>
        <option value="bank">银行流水</option><option value="input_invoice">进项发票</option><option value="output_invoice">销项发票</option><option value="sales">销售订单</option><option value="purchase">采购订单</option><option value="expense">经营费用</option><option value="contract">合同</option><option value="other">其他</option>
      </select></label>
      <label>所属月份<input type="month" value={period} onChange={e=>setPeriod(e.target.value)} required/></label>
      <label>业务系统（可选）<input value={sourceSystem} onChange={e=>setSourceSystem(e.target.value)} placeholder="coffee.purchase"/></label>
      <label>单据 ID（可选）<input value={sourceId} onChange={e=>setSourceId(e.target.value)} placeholder="已有业务单 ID"/></label>
      <button className="primary-button" disabled={busy||!sourceFile}>{busy?'保存中…':'保存原始凭证'}</button>
    </form>
    {status&&<p>{status}</p>}
    <div className="data-table">
      <div className="data-head"><span>原件</span><span>类别</span><span>月份</span><span>大小</span><span>操作</span></div>
      {rows.slice(0,30).map(row=><div className="data-row" key={row.id+row.original_name+row.created_at}>
        <span><strong>{row.original_name}</strong><small>SHA-256 {row.sha256.slice(0,14)}…</small></span>
        <span>{row.category}</span><span>{row.period}</span><span>{(row.size_bytes/1024).toFixed(1)} KB</span>
        <a href={`/api/archive/files/${row.id}/download`} className="text-link">下载原件</a>
      </div>)}
      {!rows.length&&<div className="empty-state">暂无原始凭证记录</div>}
    </div>
    <p>本功能仅在本机 API 使用。完整身份权限、NAS 备份、云端 WORM 保管及电子会计档案合规验收尚未完成。</p>
  </div>
}

function InvoiceForm({send}:{send:(path:string,payload:unknown)=>Promise<unknown>}){
  const [error,setError]=useState('');
  const [file,setFile]=useState<File|null>(null);
  const [busy,setBusy]=useState(false);
  async function submit(e:React.FormEvent<HTMLFormElement>){
    e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const d=Object.fromEntries(f.entries());
    setError('');setBusy(true);
    try{
      if(!file)throw new Error('请上传电子发票原件，归档成功后才能登记新发票');
      const period=String(d.issued_on).slice(0,7);
      const evidence=await archiveOriginal(file,d.direction==='purchase'?'input_invoice':'output_invoice',period,'finance.invoice');
      const result=await send('/api/invoices',{...d,archive_file_id:evidence.id,total_amount:d.total_amount,tax_amount:d.tax_amount||'0'});
      if(result){form.reset();setFile(null)}else setError('发票原件已留存，但发票信息未登记，请核对后台错误')
    }catch(e){setError(e instanceof Error?e.message:'发票归档或登记失败')}finally{setBusy(false)}
  }
  return <form className="panel invoice-form" onSubmit={e=>void submit(e)}>
    <h2>登记进销项发票</h2><p>先保存原件，再记录发票；内部认领不等于税局抵扣确认。</p>
    <label>电子发票原件<input type="file" accept=".pdf,.ofd,.xml" required onChange={e=>setFile(e.target.files?.[0]||null)}/></label>
    <label>发票号码<input name="invoice_number" required/></label>
    <label>方向<select name="direction"><option value="purchase">进项发票</option><option value="sales">销项发票</option></select></label>
    <label>往来单位<input name="counterparty" required/></label>
    <label>开票日期<input type="date" name="issued_on" required/></label>
    <div className="form-split"><label>价税合计<input name="total_amount" inputMode="decimal" required/></label><label>税额<input name="tax_amount" inputMode="decimal" defaultValue="0" required/></label></div>
    <div className="form-split"><label>币种<input name="currency" defaultValue="CNY" required/></label><label>记账汇率<input name="exchange_rate" inputMode="decimal" defaultValue="1" required/></label></div>
    <label>汇率日期<input type="date" name="rate_date" required/></label>
    <label>来源凭证键<input name="source_key" required placeholder="开票方税号 + 发票号码等稳定标识"/></label>
    {error&&<p className="form-error">{error}</p>}
    <button className="primary-button" disabled={busy}>{busy?'归档并登记中…':'归档并登记发票'}</button>
  </form>
}

type CsvRow = Record<string,string>
type ImportResult = {source_row_key:string;status:'posted'|'duplicate'|'rejected';message:string}
function parseCsv(text:string): string[][] {
  const rows:string[][]=[]; let row:string[]=[]; let cell=''; let quoted=false
  for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"'){quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else{cell+=ch}}
  row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows
}
function PackagingRulesWorkspace({rules,refresh}:{rules:PackagingRule[];refresh:()=>Promise<void>}) {
  const [editing,setEditing]=useState<string|null>(null);const [included,setIncluded]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  function edit(rule?:PackagingRule){setEditing(rule?.sku??'');setIncluded(Boolean(rule?.packaging_included));const form=document.getElementById('packaging-rule-form') as HTMLFormElement|null;form?.reset();if(form&&rule){(form.elements.namedItem('sku') as HTMLInputElement).value=rule.sku;(form.elements.namedItem('packaging_sku') as HTMLInputElement).value=rule.packaging_sku||'';(form.elements.namedItem('packaging_per_unit') as HTMLInputElement).value=String(rule.packaging_per_unit)}}
  async function save(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const data=Object.fromEntries(new FormData(form).entries());setError('');setBusy(true);try{const response=await fetch('/api/packaging-rules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,packaging_per_unit:Number(data.packaging_per_unit||0),packaging_included:included})});const result=await response.json();if(!response.ok)throw new Error(result.error||'包装规则保存失败');form.reset();setEditing(null);setIncluded(false);await refresh()}catch(e){setError(e instanceof Error?e.message:'本地 API 不可用')}finally{setBusy(false)}}
  return <div className="inventory-workspace"><div className="panel stock-list"><div className="panel-heading"><div><h2>SKU 包装规则</h2><p>销售导入时按商品 SKU 自动套用；工厂已含包装的商品不会重复扣盒。</p></div><span className="table-count">{rules.length} 条规则</span></div>{rules.length?<div className="data-table"><div className="data-head inventory-head"><span>商品 SKU</span><span>包装策略</span><span>操作</span></div>{rules.map(rule=><div className="data-row inventory-row" key={rule.sku}><span><strong>{rule.sku}</strong></span><span>{rule.packaging_included?'工厂已含包装，不重复扣盒':rule.packaging_per_unit>0?`每件扣 ${rule.packaging_per_unit} 个 · ${rule.packaging_sku}`:'无额外包装耗用'}</span><span><button className="secondary-button" onClick={()=>edit(rule)}>编辑</button></span></div>)}</div>:<div className="empty-state"><PackageIcon size={22}/><strong>尚未配置包装规则</strong><span>先为销售商品 SKU 设置规则，导入时系统会根据规则扣减盒子库存。</span></div>}</div><form id="packaging-rule-form" className="panel purchase-form" onSubmit={save}><h2>{editing?'编辑包装规则':'新增包装规则'}</h2><p>每个销售商品 SKU 需要一条规则；数量为 0 表示没有额外盒子耗用。</p><label>商品 SKU<input name="sku" required disabled={Boolean(editing)} placeholder="COFFEE-01"/></label><label className="checkbox-label"><input type="checkbox" checked={included} onChange={e=>setIncluded(e.target.checked)}/> 工厂已含包装</label><div className="form-split"><label>包装 SKU<input name="packaging_sku" disabled={included} placeholder="BOX-01"/></label><label>每件商品耗用盒数<input name="packaging_per_unit" type="number" min="0" step="1" defaultValue="0" disabled={included}/></label></div>{error&&<div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy?'保存中…':'保存规则'}</button>{editing&&<button type="button" className="secondary-button" onClick={()=>{setEditing(null);setIncluded(false);(document.getElementById('packaging-rule-form') as HTMLFormElement|null)?.reset()}}>取消编辑</button>}</form></div>
}

type BikeSaleField='alsvid_order_no'|'external_order_no'|'channel'|'quantity'|'net_revenue'|'sold_on'|'currency'|'exchange_rate'|'rate_date'|'source_row_key'
type BikeSaleImportResult={key:string;status:'posted'|'duplicate'|'rejected';message:string}
const bikeSaleFieldLabels:Record<BikeSaleField,string>={alsvid_order_no:'ALSVID 采购单号',external_order_no:'渠道订单号',channel:'渠道',quantity:'销售数量',net_revenue:'不含税收入',sold_on:'销售日期',currency:'币种',exchange_rate:'记账汇率',rate_date:'汇率日期',source_row_key:'来源行号'}
function BikeSalesWorkspace({orders,sales,refresh}:{orders:BikeOrder[];sales:BikeSale[];refresh:()=>Promise<void>}){
  const [fileName,setFileName]=useState('');const [headers,setHeaders]=useState<string[]>([]);const [rows,setRows]=useState<string[][]>([]);const [map,setMap]=useState<Record<BikeSaleField,string>>({alsvid_order_no:'',external_order_no:'',channel:'',quantity:'',net_revenue:'',sold_on:'',currency:'',exchange_rate:'',rate_date:'',source_row_key:''});const [results,setResults]=useState<BikeSaleImportResult[]>([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  async function choose(file?:File){if(!file)return;setError('');setResults([]);setFileName(file.name);try{if(!/\.csv$/i.test(file.name))throw new Error('当前只支持 UTF-8 CSV；请先将源文件另存为 CSV。');const parsed=parseCsv(await file.text());if(parsed.length<2)throw new Error('文件必须包含表头和至少一条明细。');const cols=parsed[0].map((v,i)=>v.trim().replace(/^\uFEFF/,'')||`列${i+1}`);setHeaders(cols);setRows(parsed.slice(1));const find=(names:string[])=>cols.find(h=>names.includes(h.trim().toLowerCase()))||'';setMap({alsvid_order_no:find(['alsvid_order_no','alsvid采购单号','采购单号','purchase_order']),external_order_no:find(['external_order_no','订单号','order_id','订单编号']),channel:find(['channel','渠道','销售渠道']),quantity:find(['quantity','qty','数量']),net_revenue:find(['net_revenue','不含税收入','收入','net sales']),sold_on:find(['sold_on','销售日期','日期','date']),currency:find(['currency','币种']),exchange_rate:find(['exchange_rate','汇率','fx_rate']),rate_date:find(['rate_date','汇率日期']),source_row_key:find(['source_row_key','来源行号','订单行号','line_id','row_id'])})}catch(e){setError(e instanceof Error?e.message:'无法读取 CSV')}}
  const consumed:Record<string,number>={}
  const prepared=rows.map((cells,index)=>{const get=(field:BikeSaleField)=>{const col=map[field];return col?cells[headers.indexOf(col)]?.trim()||'':''};const orderNo=get('alsvid_order_no');const order=orders.find(x=>x.alsvid_order_no===orderNo);const sourceRow=get('source_row_key');const channel=get('channel').toLowerCase();const key=sourceRow?`${channel}:${sourceRow}`:'';const currency=get('currency').toUpperCase();const qtyText=get('quantity');const quantity=/^\d+$/.test(qtyText)?Number(qtyText):0;const revenueText=get('net_revenue').replace(/[,$€£¥￥\s]/g,'');const revenue=Number(revenueText);const soldOn=get('sold_on');const rateText=get('exchange_rate');const rate=rateText?Number(rateText):currency==='CNY'?1:NaN;const rateDate=get('rate_date')||soldOn;const errors:string[]=[];const requiredFields:BikeSaleField[]=['alsvid_order_no','external_order_no','channel','quantity','net_revenue','sold_on','currency','source_row_key'];for(const field of requiredFields)if(!map[field]||!get(field))errors.push(`${bikeSaleFieldLabels[field]}缺失`);if(!order&&orderNo)errors.push('ALSVID 采购引用不存在');if(!/^\d{4}-\d{2}-\d{2}$/.test(soldOn)||!Number.isFinite(Date.parse(`${soldOn}T00:00:00`)))errors.push('销售日期须为 YYYY-MM-DD');if(!quantity)errors.push('数量必须是正整数');if(!Number.isFinite(revenue)||revenue<=0)errors.push('不含税收入必须为正数');if(!['CNY','EUR'].includes(currency))errors.push('币种只支持 CNY 或 EUR');if(currency==='EUR'&&!map.exchange_rate)errors.push('EUR 销售必须映射记账汇率');if(!Number.isFinite(rate)||rate<=0)errors.push('汇率必须为正数');if(!/^\d{4}-\d{2}-\d{2}$/.test(rateDate))errors.push('汇率日期须为 YYYY-MM-DD');if(key&&sales.some(row=>row.source_key===key))errors.push('已导入的来源行（重复）');if(order&&quantity>order.available_to_sell-(consumed[order.id]||0))errors.push(`超出该采购引用剩余数量 ${Math.max(0,order.available_to_sell-(consumed[order.id]||0))}`);if(order&&!errors.length)consumed[order.id]=(consumed[order.id]||0)+quantity;return {index,cells,order,key,quantity,revenue,currency,rate,rateDate,soldOn,errors,payload:{source_key:key,source:fileName,alsvid_order_no:orderNo,external_order_no:get('external_order_no'),channel:get('channel'),quantity,net_revenue:revenueText,sold_on:soldOn,currency,exchange_rate:String(rate),rate_date:rateDate}}})
  const fields=Object.keys(bikeSaleFieldLabels) as BikeSaleField[];const valid=prepared.filter(row=>!row.errors.length);const grossPreview=sales.reduce((sum,row)=>sum+Number(row.revenue_cny)-Number(row.cogs_cny),0)
  async function submit(){setError('');setBusy(true);const out=[...results];for(const row of valid){try{const response=await fetch('/api/bike/sales/import-row',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(row.payload)});const data=await response.json();out.push({key:row.key,status:response.status===200?'duplicate':response.ok?'posted':'rejected',message:response.status===200?'来源行已存在':response.ok?`已过账，毛利 CNY ${data.gross_margin_cny}`:data.error||'导入失败'})}catch(e){out.push({key:row.key,status:'rejected',message:e instanceof Error?e.message:'本地 API 不可用'})}setResults([...out])}setBusy(false);await refresh()}
  return <section className="bike-workspace"><div className="bike-sales-layout"><div className="panel import-panel"><div className="panel-heading"><div><h2>渠道销售导入</h2><p>每条销售行必须关联 ALSVID 采购引用，按已登记批次成本计算销售毛利并生成总账分录。</p></div><span className="local-only">本地处理</span></div><label className="file-drop"><FileSpreadsheet size={22}/><strong>{fileName||'选择自行车销售 CSV'}</strong><span>文件只在本地浏览器读取，不会发送到外部服务。</span><input type="file" accept=".csv,text/csv" onChange={e=>void choose(e.target.files?.[0])}/></label>{error&&<div className="form-error">{error}</div>}{headers.length>0&&<><div className="mapping-grid bike-sale-mapping">{fields.map(field=><label key={field}>{bikeSaleFieldLabels[field]}<select value={map[field]} onChange={e=>setMap({...map,[field]:e.target.value})}><option value="">请选择列</option>{headers.map(header=><option key={header} value={header}>{header}</option>)}</select></label>)}</div><div className="preview-summary"><span>共 {rows.length} 行</span><span className="good">可导入 {valid.length}</span><span className={rows.length-valid.length?'bad':''}>需复核 {rows.length-valid.length}</span><button className="primary-button" disabled={busy||!valid.length} onClick={()=>void submit()}>{busy?'逐行处理…':'确认导入有效行'}</button></div><div className="import-table-wrap"><table className="import-table"><thead><tr><th>来源行</th><th>ALSVID 批次</th><th>渠道订单</th><th>数量</th><th>收入</th><th>校验</th></tr></thead><tbody>{prepared.slice(0,100).map(row=>{const result=results.find(x=>x.key===row.key);return <tr key={`${row.key}:${row.index}`}><td>{row.key||'—'}</td><td>{row.order?.alsvid_order_no||'—'}</td><td>{row.payload.external_order_no||'—'}</td><td>{row.quantity||'—'}</td><td>{row.currency} {row.payload.net_revenue||'—'}</td><td><span className={`row-result ${result?.status||(!row.errors.length?'ready':'rejected')}`}>{result?.message||row.errors.join('；')||'可导入'}</span></td></tr>})}</tbody></table>{rows.length>100&&<div className="empty-inline">预览前 100 行；共 {rows.length} 行。</div>}</div></>}</div><aside className="panel import-rules"><h2>自行车毛利预览</h2><strong className="bike-gross-preview">CNY {grossPreview.toFixed(2)}</strong><p>已导入 {sales.length} 条销售行</p><div className="form-error bike-accounting-note">销售确认会生成 CNY 总账收入与成本分录，并按原币形成应收。导入数量必须低于已录入的 ALSVID 实收可售数量；该实收记录由操作人按外部来源行确认。</div><ul><li>不含税收入按原币和汇率折成人民币。</li><li>成本使用订单合同与已录入可资本化费用，并按辆平均分摊。</li><li>来源行号按渠道稳定键防重；销售数量不能超过已核对的 ALSVID 实收未售数量。</li><li>成本分摊锁定在首条销售导入前；更正需后续的调整流程。</li></ul></aside></div><div className="panel finance-panel"><div className="panel-heading"><div><h2>已导入自行车销售</h2><p>已过账销售及成本；外部实收证据应与来源行核对。</p></div></div>{sales.length?sales.slice(0,100).map(row=><div className="data-row" key={row.id}><span><strong>{row.sold_on} · {row.channel}</strong><small>{row.external_order_no} · 来源 {row.source}</small></span><span><strong>{row.alsvid_order_no}</strong><small>{row.quantity} 辆</small></span><span>{row.currency} {row.net_revenue}<small>折合 CNY {row.revenue_cny}</small></span><span>成本 CNY {row.cogs_cny}<small>单辆 {row.unit_landed_cost_cny}</small></span><span>来源 {row.source_key}</span></div>):<div className="empty-state"><Bike size={22}/><strong>暂无自行车销售行</strong><span>导入含 ALSVID 批次引用的 CSV 后会显示原币收入和参考成本。</span></div>}</div></section>
}

function SalesImport({inventory,packagingRules,refresh}:{inventory:InventoryRow[];packagingRules:PackagingRule[];refresh:()=>Promise<void>}) {
  const [headers,setHeaders]=useState<string[]>([]);const [rows,setRows]=useState<CsvRow[]>([]);const [fileName,setFileName]=useState('');const [originalFile,setOriginalFile]=useState<File|null>(null);const [entityCode,setEntityCode]=useState('main');const [projectCode,setProjectCode]=useState('');const [map,setMap]=useState({sku:'',quantity:'',unit_price:'',sold_on:'',source_row_key:'',channel:'',store_name:'',external_order_no:'',external_line_id:''});const [results,setResults]=useState<ImportResult[]>([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  async function choose(file?:File){if(!file)return;setError('');setResults([]);setFileName(file.name);setOriginalFile(file);if(!/\.csv$/i.test(file.name)){setError('当前仅支持 CSV。Excel 请先另存为 CSV，并确认 UTF-8 编码。');return}const parsed=parseCsv(await file.text());if(parsed.length<2){setError('文件必须包含表头和至少一条数据。');return}const cols=parsed[0].map((v,i)=>v.trim()||`列${i+1}`);setHeaders(cols);setRows(parsed.slice(1).map(c=>Object.fromEntries(cols.map((h,i)=>[h,(c[i]??'').trim()]))));const find=(names:string[])=>cols.find(h=>names.some(n=>h.toLowerCase()===n.toLowerCase()))||'';setMap({sku:find(['sku','商品sku','商品编码']),quantity:find(['quantity','qty','数量']),unit_price:find(['unit_price','price','单价','销售单价']),sold_on:find(['sold_on','date','销售日期','日期']),source_row_key:find(['source_row_key','row_id','来源行号','订单行号','line_id','行号']),channel:find(['channel','platform','platform_name','渠道','销售渠道','平台']),store_name:find(['store_name','shop','shop_name','店铺','店铺名称','商家店铺']),external_order_no:find(['external_order_no','order_id','订单号','订单编号','主订单号']),external_line_id:find(['external_line_id','order_line_id','item_id','子订单号','订单行号','明细编号','订单明细编号'])})}
  const businessKey=(row:CsvRow)=>JSON.stringify([(row[map.channel]||'').trim().toLowerCase(),(row[map.store_name]||'').trim().toLowerCase(),(row[map.external_order_no]||'').trim(),(row[map.external_line_id]||'').trim()])
  const sourceRowCounts=useMemo(()=>rows.reduce((counts,row)=>{const key=businessKey(row);counts.set(key,(counts.get(key)||0)+1);return counts},new Map<string,number>()),[rows,map.channel,map.store_name,map.external_order_no,map.external_line_id])
  function reason(row:CsvRow){const sourceRow=map.source_row_key?row[map.source_row_key]?.trim():'';if(!map.channel||!map.store_name||!map.external_order_no||!map.external_line_id)return '必须映射渠道、店铺、订单号、订单行号';if(!row[map.channel]?.trim()||!row[map.store_name]?.trim()||!row[map.external_order_no]?.trim()||!row[map.external_line_id]?.trim())return '销售业务标识不能为空';if((sourceRowCounts.get(businessKey(row))||0)>1)return '本文件重复订单明细，请先复核';const sku=row[map.sku];const itemRows=inventory.filter(i=>i.sku===sku);const rule=packagingRules.find(x=>x.sku===sku);if(!map.sku||!map.quantity||!map.unit_price||!map.source_row_key||!sku||!sourceRow||!Number.isInteger(Number(row[map.quantity]))||Number(row[map.quantity])<=0||!Number.isFinite(Number(row[map.unit_price]))||Number(row[map.unit_price])<0)return '字段缺失或格式无效';if(!rule)return 'SKU 包装规则缺失';if(itemRows.length!==1||itemRows[0].currency!=='CNY')return '商品库存不存在、币种不符或存在多币种库存';if(rule.packaging_per_unit>0&&!rule.packaging_included){const packageRows=inventory.filter(i=>i.sku===rule.packaging_sku);if(packageRows.length!==1||packageRows[0].currency!=='CNY'||packageRows[0].currency!==itemRows[0].currency)return '包装库存不存在或币种不符'}return ''}
  const valid=rows.filter(row=>!reason(row));const invalid=rows.length-valid.length
  async function submit(){if(!originalFile){setError('请先选择原始销售文件');return}setError('');setBusy(true);const out:ImportResult[]=[];try{
    const period=map.sold_on&&valid[0]?.[map.sold_on]?valid[0][map.sold_on].slice(0,7):new Date().toISOString().slice(0,7);
    const evidence=await archiveOriginal(originalFile,'sales',period,'coffee.sales');
    for(const row of valid){const dateValue=map.sold_on?row[map.sold_on]:new Date().toISOString().slice(0,10);const sourceRow=row[map.source_row_key];const payload={source_row_key:`${fileName}:${sourceRow}`,source:fileName,source_file:fileName,archive_file_id:evidence.id,event_type:'sale',sold_on:dateValue,sku:row[map.sku],quantity:Number(row[map.quantity]),unit_price:row[map.unit_price],channel:row[map.channel],store_name:row[map.store_name],external_order_no:row[map.external_order_no],external_line_id:row[map.external_line_id],business_line:'coffee',entity_code:entityCode,project_code:projectCode||null};try{const resp=await fetch('/api/sales/import-row',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await resp.json();out.push({source_row_key:sourceRow,status:resp.status===200?'duplicate':resp.ok?'posted':'rejected',message:resp.status===200?'该来源行此前已处理':resp.ok?`已过账，成本 ¥${data.result.cost_of_goods_sold}`:data.result?.error||data.error||'导入失败'})}catch(e){out.push({source_row_key:sourceRow,status:'rejected',message:e instanceof Error?e.message:'本地 API 不可用'})}setResults([...out])}
    await refresh()
  }catch(e){setError(e instanceof Error?e.message:'销售文件归档或导入失败')}finally{setBusy(false)}}
  return <div className="sales-import"><div className="panel import-panel"><div className="panel-heading"><div><h2>渠道销售明细导入</h2><p>先匹配列并预览，再按来源行逐条确认；重复导入不会重复扣减库存。</p></div><span className="local-only">本地处理</span></div><label className="file-drop"><FileSpreadsheet size={22}/><strong>{fileName||'选择 CSV 销售文件'}</strong><span>文件只在本机浏览器读取，不会上传到外部服务。</span><input type="file" accept=".csv,text/csv" onChange={e=>void choose(e.target.files?.[0])}/></label>{error&&<div className="form-error">{error}</div>}{headers.length>0&&<><div className="form-split import-dimensions"><label>经营主体编码<input value={entityCode} onChange={e=>setEntityCode(e.target.value)} required/></label><label>项目编码（可选）<input value={projectCode} onChange={e=>setProjectCode(e.target.value)}/></label></div><div className="mapping-title"><strong>字段映射</strong><span>按渠道＋店铺＋订单号＋订单行号识别同一销售，重命名文件不会重复过账。确认导入前系统会先保存完整原件，再记录关联业务行。</span></div><div className="mapping-grid">{([['sku','商品 SKU'],['quantity','销售数量'],['unit_price','不含税销售单价'],['sold_on','销售日期（可选）'],['source_row_key','文件来源行号'],['channel','销售渠道（必填）'],['store_name','店铺（必填）'],['external_order_no','原始订单号（必填）'],['external_line_id','订单行号（必填）']] as const).map(([key,label])=><label key={key}>{label}<select value={map[key]} onChange={e=>setMap({...map,[key]:e.target.value})}><option value="">请选择列</option>{headers.map(h=><option key={h} value={h}>{h}</option>)}</select></label>)}</div><div className="preview-summary"><span>共 {rows.length} 行</span><span className="good">可导入 {valid.length}</span><span className={invalid?'bad':''}>需复核 {invalid}</span><button className="primary-button" disabled={busy||valid.length===0} onClick={()=>void submit()}>{busy?'逐行处理…':'确认导入'}</button></div><div className="import-table-wrap"><table className="import-table"><thead><tr><th>来源行号</th><th>SKU</th><th>数量</th><th>单价</th><th>日期</th><th>校验</th></tr></thead><tbody>{rows.slice(0,100).map((row,i)=>{const reasonText=reason(row);const source=map.source_row_key?row[map.source_row_key]:'';const result=results.find(x=>x.source_row_key===source);return <tr key={i}><td>{source||'—'}</td><td>{map.sku?row[map.sku]||'—':'—'}</td><td>{map.quantity?row[map.quantity]||'—':'—'}</td><td>{map.unit_price?row[map.unit_price]||'—':'—'}</td><td>{map.sold_on?row[map.sold_on]||'使用今天':'使用今天'}</td><td><span className={`row-result ${result?.status|| (!reasonText?'ready':'rejected')}`}>{result?.message|| (reasonText||'可导入')}</span></td></tr>})}</tbody></table>{rows.length>100&&<div className="empty-inline">预览前 100 行；共 {rows.length} 行。</div>}</div></>}</div><aside className="panel import-rules"><h2>导入规则</h2><ul><li>每行必须填写渠道、店铺、订单号、订单行号、SKU、数量及不含税单价；来源行号用于审计定位。</li><li>相同订单明细即使存在于其他文件或文件被改名，也不得重复扣库存。同键异内容须人工复核。</li><li>SKU 不存在或库存不足会拒绝该行，不会创建负库存。</li><li>成本按 FIFO 批次计算；包装耗用按 SKU 包装规则自动扣减，工厂已含包装时不重复扣盒。当前只允许人民币库存销售。</li><li>当前只支持 CSV；不会猜测 Excel 表头或渠道模板。</li></ul></aside></div>
}
function Metric({ title, value, change, trend, icon: Icon, caption, chart, tone = 'blue' }: { title: string; value: string; change: string; trend: string; icon: React.ElementType; caption: string; chart: number[]; tone?: string }) {
  return <article className="panel metric-card"><div className="metric-top"><span>{title}</span><span className={`metric-icon ${tone}`}><Icon size={16}/></span></div><div className="metric-value">{value}</div><div className="metric-meta"><span className={`metric-change ${trend}`}>{trend === 'up' && <ArrowUpRight size={13}/>} {change}</span></div><div className="metric-foot"><span>{caption}</span>{chart.length>1&&<svg viewBox="0 0 108 34" preserveAspectRatio="none" aria-hidden="true"><polyline points={chart.map((v, i) => `${(i / (chart.length - 1)) * 108},${32 - v * .29}`).join(' ')}/></svg>}</div></article>
}

function Legend({ color, label, value, percent }: { color: string; label: string; value: string; percent: string }) { return <div className="legend-row"><span><i className={`legend-dot ${color}`}/>{label}</span><strong>{value}</strong><small>{percent}</small></div> }
function CreateOption({ icon: Icon, title, desc, onClick }: { icon: React.ElementType; title: string; desc: string; onClick: () => void }) { return <button className="create-option" onClick={onClick}><span><Icon size={17}/></span><span><strong>{title}</strong><small>{desc}</small></span><ArrowRight size={15}/></button> }
function PackageIcon({ size = 16 }: { size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 8 9 5 9-5M3 8v9l9 5 9-5V8M12 13v9"/></svg> }

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>)
























